/**
 * config 域：外部输入 → 合法设置。三个来源（磁盘配置文件、组合层 entry、HTTP patch）都**不受信**，这里是它们进入
 * 设置模型的唯一闸门。三道工序不可互换：归一化**永不失败**、校验**只审显式提交**（缺键不是错误）、净化**只留认识的键**。
 */
import {
  BUILTIN_CHANNEL_TYPES,
  WEBHOOK_AUTHS,
  WEBHOOK_PRESETS,
  isClockText,
  isSoundId,
} from "../../../../shared/interface.ts";
import { DEFAULT_CONFIG } from "../model/index.ts";
import { QUIET_WINDOWS_LIMIT } from "../model/type.ts";
import type {
  BarkChannelConfig,
  BarkLevel,
  BrowserChannelConfig,
  BuiltinChannelType,
  ChannelConfig,
  NotifyConfig,
  QuietHoursConfig,
  QuietWindow,
  RawSettingValue,
  SettingsPatch,
  SoundSetting,
  StoredSettings,
  SystemChannelConfig,
  WebhookChannelConfig,
} from "../model/type.ts";
import type { ValidationResult } from "./type.ts";

// ---------------------------------------------------------------- 合法域

// 内置音色白名单的事实源在 src/shared/sounds.ts（两端共享面），本域只消费：
// 写入口径与设置页的选项必须是同一份白名单，各写一份就会出现「页面选得到、宿主拒收」。
// 「白名单 ⊆ 音色表」这条不变量由 test/unit/shared/sounds.test.ts 守着。

// 内置频道类型的事实源在 src/shared/channels.ts（顺序即卡片顺序）：它们恒在场，是 `channels` 里
// 唯一不可删除的项——身份由 `type` 唯一确定。

/** bark 紧急度白名单。 */
const BARK_LEVELS: readonly BarkLevel[] = ["active", "timeSensitive", "passive", "critical"];

// webhook 认证方式与预设白名单的事实源在 src/shared/webhooks.ts（两端共享面）：设置页的选项与
// 写入口径必须是同一份，各写一份就会出现「页面选得到、宿主拒收」。

/** `"HH:MM"` 二十四小时制：事实源在 src/shared/quiet.ts（`isClockText`），两端同源。 */

/**
 * 频道实例里**合法的凭据只能走已知字段**（bark 的 `deviceKey`、webhook 的 `token`/`password`/`headerValue`），
 * 这些凭据别名键在写入口径直接**拒绝**而不是静默剔除——静默剔除会让用户以为设置生效了。
 *
 * 导出是为了让判据按清单表驱动：README 的「保留键写拒」与这份清单必须是同一份事实源。
 */
export const BARK_RESERVED_KEYS: readonly string[] = ["device_key", "device_keys", "ciphertext"];

/** webhook 侧的凭据别名键；与 `BARK_RESERVED_KEYS` 同语义（见上）。 */
export const WEBHOOK_RESERVED_KEYS: readonly string[] = [
  "auth_token",
  "access_token",
  "bearer_token",
  "api_key",
  "apikey",
  "client_secret",
  "secret",
  "password_hash",
];

/**
 * 频道实例的已知键。校验与归一化**共用这一份**——未知键的判定正是拿它做的减法，两处各写一份清单，
 * 「什么算未知」就会在两个工序里给出两种答案。
 */
const BARK_KNOWN_KEYS: readonly string[] = [
  "id",
  "type",
  "enabled",
  "name",
  "baseUrl",
  "deviceKey",
  "level",
  "levels",
  "group",
  "sound",
  "icon",
  "url",
  "badge",
  "timeoutMs",
];

const WEBHOOK_KNOWN_KEYS: readonly string[] = [
  "id",
  "type",
  "enabled",
  "name",
  "url",
  "preset",
  "auth",
  "token",
  "username",
  "password",
  "headerName",
  "headerValue",
  "template",
  "headers",
  "timeoutSec",
];

/**
 * 契约认识的键。从默认设置派生而不是另抄一份清单：模型新增键时白名单自动跟上，否则
 * 就是「加了键却忘了加白名单，该键永远写不进去」这种沉默故障。
 */
const CONFIG_KEYS: readonly string[] = Object.keys(DEFAULT_CONFIG);

/**
 * 只接受布尔值的键。
 *
 * 导出而非私有：门禁 `config-matrix` 要按真实取值断言「这份清单是默认设置的子集且值都是布尔」，
 * 让它读定义处才是唯一事实源——照抄一份给门禁，两边迟早各说各话。
 */
export const BOOLEAN_KEYS: readonly string[] = [
  "notifyAsk",
  "notifyQuestion",
  "notifyTaskDone",
  "notifySubagentDone",
  "notifyTaskError",
  "notifyTurnEnd",
];

/** 0.2.3 顶层渠道键的退役话术：0.2.4 起它们由 upgrade 域在装配期搬进 `channels` 的内置条目并删除。 */
const MOVED_INTO_CHANNELS_HINT =
  "该键在 0.2.4 升级时已移入渠道条目；页面停留在升级前时，刷新后重试";

/** `maxConnections` 的退役话术：0.2.5 移除了连接上限机制，本键没有后继键——说成「已移入渠道条目」会把用户引到另一种原因上。 */
const CONNECTION_CAP_REMOVED_HINT =
  "该键在 0.2.5 升级时已随 SSE 连接上限机制一并移除；页面停留在升级前时，刷新后重试";

/**
 * 退役键：**曾经**是合法配置键、现已没有值语义的键，写面一律 400 拒收，且每键自带拒收话术。
 *
 * 为什么拒而不是当陌生键放行：陌生键是留给未来版本的空间，而这一批是**已经搬走 / 已经删除**的键——
 * 静默放行会让停留在升级前页面上的旧客户端以为保存成功了。话术逐键给出而不是共用一句：0.2.3 那批只是
 * 搬了家，`maxConnections` 是机制整体移除，共用一句会把后者引到错误的原因上。
 */
export const RETIRED_KEYS: Readonly<Record<string, string>> = {
  systemEnabled: MOVED_INTO_CHANNELS_HINT,
  browserEnabled: MOVED_INTO_CHANNELS_HINT,
  systemNotify: MOVED_INTO_CHANNELS_HINT,
  browserNotify: MOVED_INTO_CHANNELS_HINT,
  notifyWhenVisible: MOVED_INTO_CHANNELS_HINT,
  notifySound: MOVED_INTO_CHANNELS_HINT,
  browserSound: MOVED_INTO_CHANNELS_HINT,
  systemSound: MOVED_INTO_CHANNELS_HINT,
  maxConnections: CONNECTION_CAP_REMOVED_HINT,
};

/**
 * 非负整数键及其上界（越界视为非法而不是截断——静默改写用户的输入比拒绝更糟）。
 *
 * 导出理由同 `BOOLEAN_KEYS`：门禁要按真实取值断言「每个键都在默认设置里且上界是非负整数」。
 */
export const COUNT_LIMITS: Record<string, number> = {
  historyMaxAgeDays: 3_650,
};

// ---------------------------------------------------------------- 解析

/**
 * 文本 → 原始设置。坏 JSON 与非对象（数组、标量）一律得到空设置：配置文件被手改成不合法
 * 内容时读面该回落默认值，而不是让整个插件装配失败——设置坏掉不该拖垮通知。
 */
export function parseJsonObject(text: string): StoredSettings {
  try {
    const parsed: RawSettingValue = JSON.parse(text);
    return isRecord(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

// ---------------------------------------------------------------- 归一化

/**
 * 归一化：把任意输入收敛成一份完整设置，缺键补默认、非法值回落合法域——**永不失败**，
 * 是读路径的必经工序。输出是**全量**的（可选字段也写出来，空串 / 空对象表达「没有」）：
 * 让形状随输入变化会迫使下游到处判键在不在，而这里正是唯一能把这件事做掉的地方。
 */
export function normalizeConfig(input: StoredSettings): NotifyConfig {
  const fallback = DEFAULT_CONFIG;
  // 渠道形态只有 `channels` 一处输出：内置两条先物化，取值链是「条目字段 → 存量的旧顶层键 → 默认表」。
  const browser = asBrowserChannel(builtinRaw(input.channels, "browser"), input);
  const system = asSystemChannel(builtinRaw(input.channels, "system"), input);
  return {
    notifyAsk: asBoolean(input.notifyAsk, fallback.notifyAsk),
    notifyQuestion: asBoolean(input.notifyQuestion, fallback.notifyQuestion),
    notifyTaskDone: asBoolean(input.notifyTaskDone, fallback.notifyTaskDone),
    notifySubagentDone: asBoolean(input.notifySubagentDone, fallback.notifySubagentDone),
    notifyTaskError: asBoolean(input.notifyTaskError, fallback.notifyTaskError),
    notifyTurnEnd: asBoolean(input.notifyTurnEnd, fallback.notifyTurnEnd),

    quietHours: asQuietHours(input.quietHours, fallback.quietHours),
    channels: [browser, system, ...outboundChannels(input.channels)],
    kindRoutes: asKindRoutes(input.kindRoutes),
    allowKinds: asStrings(input.allowKinds),

    historyMaxAgeDays: asCount(
      input.historyMaxAgeDays,
      fallback.historyMaxAgeDays,
      COUNT_LIMITS.historyMaxAgeDays,
    ),
  };
}

// ---------------------------------------------------------------- 校验

/**
 * 校验：给出首个非法键与提示。只对**显式提交**的键负责——缺键不是错误，由归一化补默认；
 * 一次只报首个非法键，因为设置页的定位光标只能落在一个字段上。陌生键不参与校验：拦下它们
 * 等于替未来的版本拒绝今天的用户（退役键是例外，见 RETIRED_KEYS）。
 */
export function validateSettings(raw: SettingsPatch): ValidationResult {
  for (const [key, value] of Object.entries(raw)) {
    if (value === undefined) continue;
    // 走 hasOwn 而不是直接索引：constructor 这类键经 JSON 提交是可能的，直接索引会摸到
    // Object.prototype 上的同名成员，把一个陌生键误判成退役键。
    const retiredHint = Object.hasOwn(RETIRED_KEYS, key) ? RETIRED_KEYS[key] : undefined;
    if (retiredHint !== undefined) return reject(key, retiredHint);
    if (!CONFIG_KEYS.includes(key)) continue;
    const verdict = validateOne(key, value);
    if (!verdict.ok) return verdict;
  }
  return { ok: true };
}

/** 单键校验；分支与归一化的取值助手一一对应，两处判断的是同一件事。 */
function validateOne(key: string, raw: RawSettingValue): ValidationResult {
  if (BOOLEAN_KEYS.includes(key)) return requireBoolean(key, raw);
  const limit = COUNT_LIMITS[key];
  if (Number.isFinite(limit)) return requireCount(key, raw, limit);
  if (key === "quietHours") return validateQuietHours(raw);
  if (key === "channels") return validateChannels(raw);
  if (key === "kindRoutes") return validateKindRoutes(raw);
  if (key === "allowKinds") return requireStringArray(key, raw);
  return { ok: true };
}

/** 布尔闸门键：`"true"` 之类的同义写法不算数——设置页提交的就是字面 boolean。 */
function requireBoolean(key: string, raw: RawSettingValue): ValidationResult {
  return typeof raw === "boolean" ? { ok: true } : reject(key, "需要 true 或 false");
}

/** 声音键：false = 静音、true = 默认音、字符串 = 内置音色名，三者之外都非法。 */
function requireSoundSetting(key: string, raw: RawSettingValue): ValidationResult {
  return typeof raw === "boolean" || isSoundId(raw)
    ? { ok: true }
    : reject(key, "需要 false、true 或内置音色名");
}

/** 计数键：闭区间 `[0, 上界]`，小数与越界都拒绝（截断会静默改写用户的输入）。 */
function requireCount(key: string, raw: RawSettingValue, limit: number): ValidationResult {
  const inRange = typeof raw === "number" && Number.isInteger(raw) && raw >= 0 && raw <= limit;
  return inRange ? { ok: true } : reject(key, `需要 0 到 ${limit} 之间的整数`);
}

/** 白名单字符串数组键。 */
function requireStringArray(key: string, raw: RawSettingValue): ValidationResult {
  return isStringArray(raw) ? { ok: true } : reject(key, "需要字符串数组");
}

// 免打扰校验：一次只报首错（key 恒为 quietHours，设置页的定位光标只能落在一个字段上，
// 真正指到第几行靠 hint 里的 windows[i] 下标）。旧形（带 start/end 却没有 windows）在这里 400：
// 升级步会把它们搬进 windows[0]，放行旧形等于让停留在升级前页面上的旧客户端以为保存成功了，
// 故提示直接给出刷新的出路。
function validateQuietHours(raw: RawSettingValue): ValidationResult {
  if (!isRecord(raw)) return reject("quietHours", "需要对象");
  if (typeof raw.enabled !== "boolean") return reject("quietHours", "缺少 enabled");
  if (raw.windows === undefined)
    return reject("quietHours", "缺少 windows（页面停留在升级前时，刷新后重试）");
  if (!Array.isArray(raw.windows)) return reject("quietHours", "windows 需要数组");
  if (raw.windows.length > QUIET_WINDOWS_LIMIT)
    return reject("quietHours", "windows 最多 " + QUIET_WINDOWS_LIMIT + " 个");
  for (let index = 0; index < raw.windows.length; index += 1) {
    const item = raw.windows[index];
    if (!isRecord(item)) return reject("quietHours", "windows[" + index + "] 需要对象");
    if (typeof item.start !== "string" || !isClockText(item.start))
      return reject("quietHours", "windows[" + index + "].start 需要 HH:MM");
    if (typeof item.end !== "string" || !isClockText(item.end))
      return reject("quietHours", "windows[" + index + "].end 需要 HH:MM");
    // 零长窗口写面直接拒：读面把它当未命中丢掉，而写面放行等于让用户存下一条永远不生效的时段。
    if (item.start === item.end)
      return reject(
        "quietHours",
        "windows[" + index + "].start 与 windows[" + index + "].end 不能相同",
      );
  }
  if ("allowKinds" in raw && !isStringArray(raw.allowKinds))
    return reject("quietHours", "allowKinds 需要字符串数组");
  return { ok: true };
}

function validateChannels(raw: RawSettingValue): ValidationResult {
  if (!Array.isArray(raw)) return reject("channels", "需要数组");
  for (const item of raw) {
    const verdict = validateChannel(item);
    if (!verdict.ok) return verdict;
  }
  return requireBuiltinsPresent(raw);
}

/**
 * 内置频道不能删除：显式提交的 `channels` 必须仍然带着它们——这是内置频道**唯一**的特殊之处，
 * 其余一律按普通条目处理。
 *
 * 做成 400 而不是静默补回：静默补回会让「我删掉了它」与「它还在」在同一份界面上各说各话。代价是
 * 停留在升级前页面上的旧客户端（草稿里没有内置条目）会被拒一次，故提示直接给出刷新的出路。
 */
function requireBuiltinsPresent(list: readonly RawSettingValue[]): ValidationResult {
  const types = new Set<RawSettingValue>();
  for (const item of list) {
    if (isRecord(item)) types.add(item.type);
  }
  for (const type of BUILTIN_CHANNEL_TYPES) {
    if (types.has(type)) continue;
    return reject("channels", `内置渠道不能删除：缺少 ${type}（页面停留在升级前时，刷新后重试）`);
  }
  return { ok: true };
}

/** `level` 与 `preset` 是可选键：缺省各有明确语义（前者让「severity → level」映射生效，后者归一到 custom），
 * 客户端新建频道时本就不带它们——照必填拦下等于让用户的合法提交保存不了。
 *
 * 导出给草稿测试（dry-run）逐项复用：它只审单条、不审「内置必须在场」（见 requireBuiltinsPresent），
 * 草稿里可以只有目标频道一条。 */
export function validateChannel(raw: RawSettingValue): ValidationResult {
  if (!isRecord(raw)) return reject("channels", "频道项需要对象");
  if (raw.type === "browser" || raw.type === "system") return validateBuiltinChannel(raw, raw.type);
  if (typeof raw.id !== "string" || raw.id === "") return reject("channels", "频道缺少 id");
  if (raw.type === "bark") return validateBarkChannel(raw, raw.id);
  if (raw.type === "webhook") return validateWebhookChannel(raw, raw.id);
  return reject("channels", "频道 type 需要 bark、webhook、browser 或 system");
}

/** 内置频道：身份由 `type` 唯一确定（`id` 只是回显，写了就必须一致），开关与声音逐个按各自值域校验。 */
function validateBuiltinChannel(
  raw: Record<string, RawSettingValue>,
  type: BuiltinChannelType,
): ValidationResult {
  if (raw.id !== undefined && raw.id !== type)
    return reject("channels", `内置频道 ${type} 的 id 只能是 ${type}`);
  for (const key of ["enabled", "popup", "whenVisible"]) {
    if (raw[key] === undefined || typeof raw[key] === "boolean") continue;
    return reject("channels", `内置频道 ${type} 的 ${key} 需要 true 或 false`);
  }
  return raw.sound === undefined ? { ok: true } : requireSoundSetting("channels", raw.sound);
}

/** bark 频道：`baseUrl` 与 `deviceKey` 是投递必需；`level` 缺省时让 severity 映射生效，故可省。 */
function validateBarkChannel(raw: Record<string, RawSettingValue>, id: string): ValidationResult {
  if (typeof raw.baseUrl !== "string" || raw.baseUrl === "")
    return reject("channels", `bark 频道 ${id} 缺少 baseUrl`);
  if (typeof raw.deviceKey !== "string" || raw.deviceKey === "")
    return reject("channels", `bark 频道 ${id} 缺少 deviceKey`);
  if (raw.level !== undefined && !isMember(raw.level, BARK_LEVELS))
    return reject("channels", `bark 频道 ${id} 的 level 非法`);
  return validateExtras(raw, id, BARK_KNOWN_KEYS, BARK_RESERVED_KEYS, "bark");
}

/** webhook 频道：`url` 与 `auth` 是投递必需；`preset` 缺省归一到 custom，故可省。 */
function validateWebhookChannel(
  raw: Record<string, RawSettingValue>,
  id: string,
): ValidationResult {
  if (typeof raw.url !== "string" || raw.url === "")
    return reject("channels", `webhook 频道 ${id} 缺少 url`);
  if (!isMember(raw.auth, WEBHOOK_AUTHS))
    return reject("channels", `webhook 频道 ${id} 的 auth 非法`);
  if (raw.preset !== undefined && !isMember(raw.preset, WEBHOOK_PRESETS))
    return reject("channels", `webhook 频道 ${id} 的 preset 非法`);
  return validateExtras(raw, id, WEBHOOK_KNOWN_KEYS, WEBHOOK_RESERVED_KEYS, "webhook");
}

/**
 * 未知键的写入口径：保留键**写拒**（400），其余只放行 string/number。
 *
 * 为什么不做成「未知键一律拒绝」：README 承诺了前向兼容——bark 将来新增的参数，用户现在写进配置
 * 就该被保留并原样带出去；而为什么不做成「一律接受」：`{}`、数组、布尔的透传值会污染生效设置，
 * 让「有值」与「没值」在下游分不清。
 */
function validateExtras(
  raw: Record<string, RawSettingValue>,
  id: string,
  known: readonly string[],
  reserved: readonly string[],
  kindLabel: string,
): ValidationResult {
  for (const key of Object.keys(raw)) {
    if (known.includes(key)) continue;
    if (reserved.includes(key))
      return reject("channels", `${kindLabel} 频道 ${id} 的 ${key} 是保留键：凭据只能走已知字段`);
    const value = raw[key];
    if (typeof value !== "string" && typeof value !== "number")
      return reject("channels", `${kindLabel} 频道 ${id} 的 ${key} 只能是字符串或数字`);
  }
  return { ok: true };
}

function validateKindRoutes(raw: RawSettingValue): ValidationResult {
  if (!isRecord(raw)) return reject("kindRoutes", "需要对象");
  for (const key of Object.keys(raw)) {
    const value = raw[key];
    if (!Array.isArray(value) || !value.every((item) => typeof item === "string")) {
      return reject("kindRoutes", `${key} 需要字符串数组`);
    }
  }
  return { ok: true };
}

function reject(key: string, hint: string): ValidationResult {
  return { ok: false, error: { key, hint } };
}

// ---------------------------------------------------------------- 净化

/**
 * 净化：只保留契约认识的键。陌生键一律剔除而不是拒绝——配置文件是共享的，别的东西写进来的
 * 键不该让设置读取失败，也不该被原样带进用户层再写回去。**不归一化**：净化只回答「这个键归
 * 不归我」，在这里顺手归一化会让写路径把用户的原始提交偷偷改写掉。
 *
 * @returns 净化后的部分设置；输入不是对象时得到空设置——「一个键都不认识」与「没有键」对
 *   调用方是同一件事，不必再给一个空值语义让它自己判。
 */
export function sanitizeSettings(raw: StoredSettings): Partial<NotifyConfig> {
  const kept: Record<string, RawSettingValue> = {};
  if (!isRecord(raw)) return kept;
  for (const key of CONFIG_KEYS) {
    const value = raw[key];
    if (value === undefined) continue;
    kept[key] = value;
  }
  return kept as Partial<NotifyConfig>;
}

// ---------------------------------------------------------------- 取值助手

/** 原始值是不是一个 JSON 对象（数组与空值不算）。 */
function isRecord(raw: RawSettingValue): raw is Record<string, RawSettingValue> {
  return typeof raw === "object" && raw !== null && !Array.isArray(raw);
}

/** 命中白名单则保留，其余（含缺键）回落。 */
function isMember<T extends string>(raw: RawSettingValue, allowed: readonly T[]): raw is T {
  return typeof raw === "string" && allowed.some((item) => item === raw);
}

/** 字符串数组：元素逐个看，非字符串即不算（与归一化侧「剔除非字符串项」是同一口径的两面）。 */
function isStringArray(raw: RawSettingValue): boolean {
  return Array.isArray(raw) && raw.every((item) => typeof item === "string");
}

function asBoolean(raw: RawSettingValue, fallback: boolean): boolean {
  return typeof raw === "boolean" ? raw : fallback;
}

function asString(raw: RawSettingValue, fallback: string): string {
  return typeof raw === "string" ? raw : fallback;
}

/** 非负整数且不越界；越界回落而不是截断（与校验的口径一致：拒绝胜过静默改写）。 */
function asCount(raw: RawSettingValue, fallback: number, limit: number): number {
  return typeof raw === "number" && Number.isInteger(raw) && raw >= 0 && raw <= limit
    ? raw
    : fallback;
}

/** 声音设置：`false` / `true` / 内置音色名三种形态；音色名非法即回落。 */
function asSound(raw: RawSettingValue, fallback: SoundSetting): SoundSetting {
  if (typeof raw === "boolean") return raw;
  return isSoundId(raw) ? raw : fallback;
}

/**
 * 旧全局声音键的**读面**回落：两个按出口的新键缺失（或非法）时先看 `notifySound`，再看默认值。
 *
 * 为什么保留这条链：存量 user 层不迁移（只在官方 settings 里写过旧键的用户），没有它，「当时关过提示音」
 * 这件事在升级后会被读成默认的 `true` —— 静音设置无声复活成有声。
 */
function legacySound(legacy: RawSettingValue, fallback: SoundSetting): SoundSetting {
  return typeof legacy === "boolean" ? legacy : fallback;
}

/** 字符串数组：非字符串项剔除而不是整组丢弃（一项脏值不该连累其余）。 */
function asStrings(raw: RawSettingValue): string[] {
  return Array.isArray(raw) ? raw.filter((item): item is string => typeof item === "string") : [];
}

// 免打扰归一化：永不失败。单项非法（格式错、零长）只废该项，不废整组；全废则等于未命中
// （沿用「脏设置不吃掉所有通知」）。windows 缺席或非数组时回落 legacy：还没跑过 0.2.6 升级的
// 文件里只有旧的 start/end，读面在这里把它们看成 windows[0]，于是老文件在升级前后行为不变；
// 显式 [] 保持 []（空数组 = 未命中，不是「缺了要补默认」）。
function asQuietHours(raw: RawSettingValue, fallback: QuietHoursConfig): QuietHoursConfig {
  // 回落交出深副本：默认表是共享的，调用方就地改写它会污染此后每一个读者（windows 是数组，
  // 浅拷贝仍与默认表共享同一份列表）。
  if (!isRecord(raw)) return copyQuietHours(fallback);
  const enabled = asBoolean(raw.enabled, fallback.enabled);
  const allowKinds = asStrings(raw.allowKinds);
  if (!Array.isArray(raw.windows)) {
    return { enabled: enabled, windows: legacyWindows(raw, fallback), allowKinds: allowKinds };
  }
  const windows: QuietWindow[] = [];
  for (const item of raw.windows) {
    const window = asQuietWindow(item);
    if (window !== null) windows.push(window);
  }
  return { enabled: enabled, windows: windows, allowKinds: allowKinds };
}

// 默认表的免打扰深副本。
function copyQuietHours(fallback: QuietHoursConfig): QuietHoursConfig {
  const copied: QuietHoursConfig = {
    enabled: fallback.enabled,
    windows: fallback.windows.map((window) => ({ ...window })),
  };
  if (fallback.allowKinds !== undefined) copied.allowKinds = [...fallback.allowKinds];
  return copied;
}

// 还没升级的文件：旧 start/end 看成 windows[0]；连旧键都没有才回落默认表。
function legacyWindows(
  raw: Record<string, RawSettingValue>,
  fallback: QuietHoursConfig,
): QuietWindow[] {
  const window = asQuietWindow({ start: raw.start, end: raw.end });
  if (window !== null) return [window];
  return fallback.windows.map((item) => ({ ...item }));
}

// 单个窗口的读面收窄；非法与零长一律丢项（返回 null），不连累同组的其余项。
function asQuietWindow(raw: RawSettingValue): QuietWindow | null {
  if (!isRecord(raw)) return null;
  if (typeof raw.start !== "string" || !isClockText(raw.start)) return null;
  if (typeof raw.end !== "string" || !isClockText(raw.end)) return null;
  if (raw.start === raw.end) return null;
  return { start: raw.start, end: raw.end };
}

/** kind → 频道 id 的稀疏路由；值不是数组的项剔除。 */
function asKindRoutes(raw: RawSettingValue): Record<string, string[]> {
  const routes: Record<string, string[]> = {};
  if (!isRecord(raw)) return routes;
  for (const key of Object.keys(raw)) {
    routes[key] = asStrings(raw[key]);
  }
  return routes;
}

/** 频道数组的逐项读取结果；认不出的项不带回值。 */
type ChannelRead = { ok: true; channel: ChannelConfig } | { ok: false };

/**
 * 出站实例数组：逐项归一化，**认不出的项直接丢弃**——一个没写 id、没写 url、没写凭据的「频道」
 * 没有任何可投递的目标，补成空壳只会在投递时制造一次必然失败的尝试。
 *
 * 内置条目在这里被跳过：它们由 `asBrowserChannel` / `asSystemChannel` 单独物化，且恒排在最前。
 */
function outboundChannels(raw: RawSettingValue): ChannelConfig[] {
  const channels: ChannelConfig[] = [];
  if (!Array.isArray(raw)) return channels;
  for (const item of raw) {
    const read = asChannel(item);
    if (read.ok) channels.push(read.channel);
  }
  return channels;
}

/** 输入数组里首个指定类型的内置条目（原始形态）；同类型的后来者被丢弃——内置身份由 `type` 唯一确定。 */
function builtinRaw(
  raw: RawSettingValue,
  type: BuiltinChannelType,
): Record<string, RawSettingValue> | undefined {
  if (!Array.isArray(raw)) return undefined;
  for (const item of raw) {
    if (isRecord(item) && item.type === type) return item;
  }
  return undefined;
}

/**
 * 浏览器频道物化：条目字段 → 存量投影键（0.2.3 的顶层键）→ 默认表。
 *
 * 别名只在这条链的末端参与，所以「用户已在新页面改过条目」与「文件里还躺着旧顶层键」不会互相覆盖
 * ——前者恒赢。这也是同一件事在文件里有两处表达却不打架的原因。
 */
function asBrowserChannel(
  raw: Record<string, RawSettingValue> | undefined,
  input: StoredSettings,
): BrowserChannelConfig {
  const fallback = builtinDefault("browser");
  const source: Record<string, RawSettingValue> = raw ?? {};
  return {
    type: "browser",
    id: "browser",
    enabled: asBoolean(source.enabled, asBoolean(input.browserEnabled, fallback.enabled)),
    popup: asBoolean(source.popup, asBoolean(input.browserNotify, fallback.popup)),
    sound: asSound(source.sound, outletSoundOf(input, input.browserSound, fallback.sound)),
    whenVisible: asBoolean(
      source.whenVisible,
      asBoolean(input.notifyWhenVisible, fallback.whenVisible),
    ),
  };
}

/** 系统频道物化：链与浏览器频道同构，只是没有 `whenVisible`——那是浏览器出口独有的展示条件。 */
function asSystemChannel(
  raw: Record<string, RawSettingValue> | undefined,
  input: StoredSettings,
): SystemChannelConfig {
  const fallback = builtinDefault("system");
  const source: Record<string, RawSettingValue> = raw ?? {};
  return {
    type: "system",
    id: "system",
    enabled: asBoolean(source.enabled, asBoolean(input.systemEnabled, fallback.enabled)),
    popup: asBoolean(source.popup, asBoolean(input.systemNotify, fallback.popup)),
    sound: asSound(source.sound, outletSoundOf(input, input.systemSound, fallback.sound)),
  };
}

/**
 * 默认表里的内置条目：物化的最后一级回落。
 *
 * 断言只为把「按 type 找到的那条」收窄成对应型号——查找条件就是 type 相等。默认表是本模块的常量，
 * 两条内置条目必然在场；真缺了当场抛错比静默降级好（那是编码错误，不是用户输入的问题）。
 */
function builtinDefault<T extends BuiltinChannelType>(
  type: T,
): Extract<ChannelConfig, { type: T }> {
  for (const channel of DEFAULT_CONFIG.channels) {
    if (channel.type === type) return channel as Extract<ChannelConfig, { type: T }>;
  }
  throw new Error(`dsh-notifier: 默认设置里缺少内置频道 ${type}`);
}

/**
 * 存量音效的物化：按出口的键（`browserSound` / `systemSound`）优先，其次旧的全局键 `notifySound`。
 *
 * 两者的值域不同，不能合在一层收窄：出口键当年就存音色名（完整声音域），全局键只有开关语义（只认布尔）
 * ——用同一个助手处理会把存量音色名吞成默认值。
 */
function outletSoundOf(
  input: StoredSettings,
  outlet: RawSettingValue,
  fallback: SoundSetting,
): SoundSetting {
  if (outlet !== undefined) return asSound(outlet, fallback);
  return legacySound(input.notifySound, fallback);
}

function asChannel(raw: RawSettingValue): ChannelRead {
  if (!isRecord(raw)) return { ok: false };
  const id = asString(raw.id, "");
  if (id === "") return { ok: false };
  if (raw.type === "bark") return asBarkChannel(raw, id);
  if (raw.type === "webhook") return asWebhookChannel(raw, id);
  return { ok: false };
}

function asBarkChannel(raw: Record<string, RawSettingValue>, id: string): ChannelRead {
  const baseUrl = asString(raw.baseUrl, "");
  const deviceKey = asString(raw.deviceKey, "");
  if (baseUrl === "" || deviceKey === "") return { ok: false };
  const channel: BarkChannelConfig = {
    type: "bark",
    id,
    enabled: asBoolean(raw.enabled, false),
    name: asString(raw.name, ""),
    baseUrl,
    deviceKey,
    group: asString(raw.group, ""),
    sound: asString(raw.sound, ""),
    icon: asString(raw.icon, ""),
    url: asString(raw.url, ""),
    timeoutMs: asCount(raw.timeoutMs, 0, 600_000),
    levels: asLevels(raw.levels),
  };
  // 紧急度不兜底：缺了它才轮到「severity → level」那层映射，兜成 active 会让 error 通知
  // 永远发不出 timeSensitive；徽标同理，0 是有意义的取值。
  if (isMember(raw.level, BARK_LEVELS)) channel.level = raw.level;
  if (typeof raw.badge === "number") channel.badge = raw.badge;
  const extras = extrasOf(raw, BARK_KNOWN_KEYS, BARK_RESERVED_KEYS);
  if (Object.keys(extras).length > 0) channel.extras = extras;
  return { ok: true, channel };
}

/**
 * 实例里的未知键：只留 string/number 值。
 *
 * 校验面已经拒掉保留键与非 string/number 值，这里再过滤一遍不是重复——归一化读的是**磁盘上的内容**，
 * 手改过的文件不经过写入口径；而保留键在这里必须剔除，否则一条手写的 `device_key` 就能绕开
 * 「凭据只能走已知字段」的收口。
 */
function extrasOf(
  raw: Record<string, RawSettingValue>,
  known: readonly string[],
  reserved: readonly string[],
): Record<string, string | number> {
  const extras: Record<string, string | number> = {};
  for (const key of Object.keys(raw)) {
    if (known.includes(key) || reserved.includes(key)) continue;
    const value = raw[key];
    if (typeof value === "string" || typeof value === "number") extras[key] = value;
  }
  return extras;
}

function asLevels(raw: RawSettingValue): Record<string, BarkLevel> {
  const levels: Record<string, BarkLevel> = {};
  if (!isRecord(raw)) return levels;
  for (const key of Object.keys(raw)) {
    const value = raw[key];
    if (isMember(value, BARK_LEVELS)) levels[key] = value;
  }
  return levels;
}

function asWebhookChannel(raw: Record<string, RawSettingValue>, id: string): ChannelRead {
  const url = asString(raw.url, "");
  if (url === "") return { ok: false };
  const channel: WebhookChannelConfig = {
    type: "webhook",
    id,
    enabled: asBoolean(raw.enabled, false),
    name: asString(raw.name, ""),
    url,
    preset: isMember(raw.preset, WEBHOOK_PRESETS) ? raw.preset : "custom",
    auth: isMember(raw.auth, WEBHOOK_AUTHS) ? raw.auth : "none",
    token: asString(raw.token, ""),
    username: asString(raw.username, ""),
    password: asString(raw.password, ""),
    headerName: asString(raw.headerName, ""),
    headerValue: asString(raw.headerValue, ""),
    template: asString(raw.template, ""),
    headers: asHeaders(raw.headers),
    timeoutSec: asCount(raw.timeoutSec, 0, 600),
  };
  const extras = extrasOf(raw, WEBHOOK_KNOWN_KEYS, WEBHOOK_RESERVED_KEYS);
  if (Object.keys(extras).length > 0) channel.extras = extras;
  return { ok: true, channel };
}

function asHeaders(raw: RawSettingValue): Record<string, string> {
  const headers: Record<string, string> = {};
  if (!isRecord(raw)) return headers;
  for (const key of Object.keys(raw)) {
    const value = raw[key];
    if (typeof value === "string") headers[key] = value;
  }
  return headers;
}

/**
 * config 域凭据的掩码往返（安全模块）：**读出去一律掩码，写回来按 id 还原**——没有这条对称，凭据只有两种结局：
 * 明文出到界面与日志，或被掩码覆盖成字面量。`CHANNEL_SECRET_FIELDS` 是唯一扩展点，两处各写一份清单一定会漂移。
 */
import type {
  ChannelConfig,
  NotifyConfig,
  RawSettingValue,
  StoredSettings,
} from "../model/type.ts";

/** 掩码占位：提交整值等于它 = 该字段「未修改」。 */
const SECRET_MASK = "********";

/** 掩码还原结果：成功带回还原后的频道数组；失败 = 有实例提交了掩码却无原值。 */
type UnmaskResult = { ok: true; channels: RawSettingValue } | { ok: false };

/** 单项还原结果；失败即「没有原值可还原」，整批随之中止。 */
type UnmaskedChannel = { ok: true; channel: RawSettingValue } | { ok: false };

/** 各频道类型的密钥字段清单。 */
const CHANNEL_SECRET_FIELDS: Record<ChannelConfig["type"], readonly string[]> = {
  bark: ["deviceKey"],
  webhook: ["token", "password", "headerValue"],
  // 内置频道没有任何凭据字段；它们在表里必须出现（Record 强制穷尽），值就是空清单。
  browser: [],
  system: [],
};

/** 读出口脱敏：深拷贝后把密钥字段掩码。拷贝而非原地改，是因为它作用于**即将外发的视图**，而同一份设置在域内还要以
 * 明文参与投递；频道项按**原始值**处理——存储层不受契约约束，里面可能躺着更高版本写的频道类型。 */
export function redactConfig(value: Partial<NotifyConfig>): Partial<NotifyConfig> {
  const copy = structuredClone(value);
  const channels = copy.channels;
  if (!Array.isArray(channels)) return copy;
  // 断言只声明"这是同一批频道，只是密钥被换成了掩码"——掩码不会改变项的形状。
  copy.channels = channels.map(maskChannel) as ChannelConfig[];
  return copy;
}

/**
 * 存储层的读出口脱敏：视图的 `user` 要**原样带陌生键**（只掩码凭据），所以不能先过净化——
 * 净化会把用户手写的未来键从视图里摘掉，而它们其实还在文件里，界面与文件就此各说各话。
 */
export function redactStored(stored: StoredSettings): StoredSettings {
  const masked: Record<string, RawSettingValue> = {};
  for (const [key, value] of Object.entries(stored)) {
    masked[key] =
      key === "channels" && Array.isArray(value)
        ? (value.map(maskChannel) as RawSettingValue)
        : structuredClone(value);
  }
  return masked;
}

/**
 * 写入口还原：patch 里等于掩码的字段，按 **id** 对齐取回原值——按下标对齐时数组顺序一变，
 * 就会把 A 实例的凭据回填进 B。
 *
 * @param patchChannels 提交上来的频道数组。
 * @param userChannels 已存储的频道数组（原值来源）；缺省视为没有原值。
 * @returns 还原后的频道数组；`ok: false` = 有实例提交了掩码却没有对应原值，调用方应当拒绝
 *   ——掩码只能表达「未修改」，不能凭空造出一个凭据。
 */
export function unmaskChannels(
  patchChannels: RawSettingValue,
  userChannels?: RawSettingValue,
): UnmaskResult {
  if (!Array.isArray(patchChannels)) return { ok: false };
  const existing: readonly RawSettingValue[] = Array.isArray(userChannels) ? userChannels : [];
  const restored: RawSettingValue[] = [];
  for (const item of patchChannels) {
    const read = unmaskChannel(item, existing);
    if (!read.ok) return { ok: false };
    restored.push(read.channel);
  }
  return { ok: true, channels: restored };
}

function maskChannel(channel: RawSettingValue): RawSettingValue {
  if (!isRecord(channel)) return channel;
  const masked: Record<string, RawSettingValue> = { ...channel };
  for (const field of secretFieldsOfType(channel.type)) {
    if (typeof masked[field] === "string") masked[field] = SECRET_MASK;
  }
  return masked;
}

function unmaskChannel(
  patch: RawSettingValue,
  existing: readonly RawSettingValue[],
): UnmaskedChannel {
  if (!isRecord(patch)) return { ok: true, channel: patch };
  const masked = secretFieldsOf(patch);
  if (masked.length === 0) return { ok: true, channel: patch };

  const original = findById(existing, idOf(patch));
  if (!original.ok) return { ok: false };

  const restored: Record<string, RawSettingValue> = { ...patch };
  for (const field of masked) {
    const value = original.channel[field];
    if (typeof value !== "string") return { ok: false };
    restored[field] = value;
  }
  return { ok: true, channel: restored };
}

/**
 * 某个频道类型的密钥字段；**不认识的类型给空清单**——配置文件里可能躺着更高版本或手写进去的
 * 频道，读出口的职责是原样送出而不是报错：在这里抛，用户看到的是设置页整页 500，而真正的原因
 * （某个陌生频道类型）没有任何线索指向它。
 */
function secretFieldsOfType(type: RawSettingValue): readonly string[] {
  if (type === "bark" || type === "webhook") return CHANNEL_SECRET_FIELDS[type];
  return [];
}

/** 提交项里**实际带了掩码**的密钥字段；不是频道对象时为空。 */
function secretFieldsOf(patch: Record<string, RawSettingValue>): readonly string[] {
  return secretFieldsOfType(patch.type).filter((field) => patch[field] === SECRET_MASK);
}

/**
 * 还原后是否还残留掩码字面量（跨 type 残留 / 改名残留）：还原只处理「当前 type 的密钥字段」，
 * `bark → webhook` 后残留的 `deviceKey: "********"` 这类字面量不会被还原——把它当真实凭据
 * 发出去等于把占位符写进对端日志，静默剥离等于替用户改配置，两条路都不对，由调用方整体拒绝。
 *
 * 扫的是**全部已知类型的密钥字段**而不只是当前 type 的：残留恰恰发生在「字段不属于当前
 * type」时，只扫当前 type 永远扫不到它。未知类型的密钥字段不在表里，扫不到——那种频道连
 * 校验都过不了，到不了这一步。
 */
export function hasResidualMask(channel: RawSettingValue): boolean {
  if (!isRecord(channel)) return false;
  for (const fields of Object.values(CHANNEL_SECRET_FIELDS)) {
    for (const field of fields) {
      if (channel[field] === SECRET_MASK) return true;
    }
  }
  return false;
}

/** 按 id 查找的结果；找不到时不带回任何值。 */
type LookupResult = { ok: true; channel: Record<string, RawSettingValue> } | { ok: false };

/** 按 id 找已存储的同名频道；id 为空或找不到时给不出原值。 */
function findById(existing: readonly RawSettingValue[], id: string): LookupResult {
  if (id === "") return { ok: false };
  for (const item of existing) {
    if (isRecord(item) && item.id === id) return { ok: true, channel: item };
  }
  return { ok: false };
}

function idOf(patch: Record<string, RawSettingValue>): string {
  const id = patch.id;
  return typeof id === "string" ? id : "";
}

function isRecord(raw: RawSettingValue): raw is Record<string, RawSettingValue> {
  return typeof raw === "object" && raw !== null && !Array.isArray(raw);
}

/**
 * dsh-notifier config 域 —— 草稿测试（dry-run）的输入闸门：只认 draft.channels。
 *
 * 与写面（write）的三处不同，每一处都是提案 B1/B2 的逐条落实：
 * - 只审 channels：draft 顶层的其它键一律忽略（不 400），revision 直接忽略——
 *   dry-run 不做乐观并发，测的是眼前条目，不是版本链；
 * - 逐项只调 validateChannel（单条），跳过 requireBuiltinsPresent——草稿里可以只有
 *   目标频道一条，要求内置在场会把「单测一个新建 bark 频道」这个主场景直接拒掉；
 * - 掩码按 id 还原（复用 unmaskChannels）：新频道无源、id 改名带掩码都落到
 *   NEW_CHANNEL_MASK_HINT 的 400；还原后仍残留掩码字面量（跨 type 残留）整体拒绝——
 *   占位符不是凭据，发出去会进对端日志，剥离会替用户改配置（B2 选 400 那一支，并由判据钉住）。
 *
 * 本模块只做「输入 → 可投递的频道数组」，不读文件、不写盘、不记日志：调用方（api 域）
 * 拿到的已是还原后的原始条目，再经 normalizeConfig 在内存里归一化，全程零落盘。
 */
import { validateChannel } from "../input/index.ts";
import type { RawSettingValue } from "../model/type.ts";
import { hasResidualMask, unmaskChannels } from "../redact/index.ts";
import { NEW_CHANNEL_MASK_HINT } from "../service/index.ts";

/** 草稿解析结论：成功带回还原后的频道数组（原始形态，调用方再归一化）；失败只带一句话。 */
export type ResolvedDraft =
  | { readonly ok: true; readonly channels: readonly RawSettingValue[] }
  | { readonly ok: false; readonly hint: string };

/** 跨 type 残留掩码的拒绝理由：占位符出现在密钥位上，说明草稿里的凭据已经对不上任何已存值。 */
const RESIDUAL_MASK_HINT = "草稿里有未还原的掩码占位（跨类型残留或改名残留），请重新填写真实凭据";

/**
 * 解析 dry-run 草稿：draft 必须是对象，其 channels 必须是数组；数组逐项校验、按 id
 * 还原掩码、再扫残留。三步任一失败即整体拒绝——半条还原的草稿没有「测一半」的语义。
 *
 * @param draft 请求体里的 draft（顶层其它键与 revision 由调用方忽略，不进这里）。
 * @param secrets 掩码还原的原值来源（调用方传已生效设置的 channels，含明文凭据、不外发）。
 */
export function resolveDraftChannels(
  draft: unknown,
  secrets: readonly RawSettingValue[] | undefined,
): ResolvedDraft {
  if (!isRecord(draft)) return fail("draft 需要对象");
  const raw = draft.channels;
  if (!Array.isArray(raw)) return fail("draft.channels 需要数组");
  for (const item of raw) {
    const verdict = validateChannel(item);
    if (!verdict.ok) return fail(verdict.error.hint);
  }
  const restored = unmaskChannels(raw, secrets);
  if (!restored.ok) return fail(NEW_CHANNEL_MASK_HINT);
  const channels = restored.channels;
  if (!Array.isArray(channels)) return fail("draft.channels 需要数组");
  for (const channel of channels) {
    if (hasResidualMask(channel)) return fail(RESIDUAL_MASK_HINT);
  }
  return { ok: true, channels };
}

function fail(hint: string): ResolvedDraft {
  return { ok: false, hint };
}

function isRecord(raw: unknown): raw is Record<string, RawSettingValue> {
  return typeof raw === "object" && raw !== null && !Array.isArray(raw);
}

/**
 * 设置默认形态。与 `type.ts` 分开：形状与默认值是两套导出面，混在一起会让只想引一个类型
 * 的调用方连同一份值表一起拖进来。
 */
import type { NotifyConfig } from "./type.ts";

/** 默认设置：缺键的兜底值，也是设置页展示的初始形态。 */
export const DEFAULT_CONFIG: NotifyConfig = {
  notifyAsk: true,
  notifyQuestion: true,
  notifyTaskDone: true,
  notifySubagentDone: false,
  notifyTaskError: true,
  notifyTurnEnd: false,

  // 渠道形态只有一处表达：下面两条内置条目。0.2.3 的顶层渠道键在升级时被搬进条目并删除。
  quietHours: { enabled: false, windows: [{ start: "22:00", end: "08:00" }] },
  // 内置频道恒在场且恒在最前：默认表就带它们，读面物化才有「与默认表逐字一致」的比对基准。
  channels: [
    { type: "browser", id: "browser", enabled: true, popup: true, sound: true, whenVisible: false },
    { type: "system", id: "system", enabled: true, popup: true, sound: true },
  ],
  kindRoutes: {},
  allowKinds: [],

  historyMaxAgeDays: 0,
};

/**
 * dsh-notifier config 域 —— 设置存取的实现：读 = 文件 → 净化 → 归一化 → 快照，写 = 掩码还原 → 校验 → 合并 → 落盘。
 *
 * 装配期同步读完文件：读面是同步的，留一个窗口就会有读者拿到尚未生效的默认值。
 */
import { createHash } from "node:crypto";
import type { ConfigDeps } from "../../deps.ts";
import {
  readTextFileSync,
  writeTextAtomic,
  CONFIG_FILE_NAME,
  notifierFile,
} from "../../../shared/interface.ts";
import {
  normalizeConfig,
  parseJsonObject,
  sanitizeSettings,
  validateSettings,
} from "../input/index.ts";
import { DEFAULT_CONFIG } from "../model/index.ts";
import type {
  NotifyConfig,
  RawSettingValue,
  SettingsPatch,
  StoredSettings,
} from "../model/type.ts";
import { redactConfig, redactStored, unmaskChannels } from "../redact/index.ts";
import type { SettingsView, WriteResult } from "./type.ts";

/** 掩码还原后的写入口 patch；失败 = patch 里的新实例提交了掩码占位。 */
type RestoredPatch = { ok: true; patch: SettingsPatch } | { ok: false };

/** 新增频道提交掩码占位时的拒绝理由（掩码只表达「未修改」，新实例没有原值可还原）。
 *
 * 导出给草稿测试（dry-run）复用同一句话：id 改名带掩码、无源新频道带掩码都是「没有原值可还原」
 * 的同一种失败，两处各写一句迟早漂成两种说法。 */
export const NEW_CHANNEL_MASK_HINT = "新增频道不能提交掩码占位，请填写真实凭据";

/** 原型链上的危险键名：JSON 文本能造出自有键，展开进设置对象就会改写原型。 */
const UNSAFE_KEYS: readonly string[] = ["__proto__", "constructor", "prototype"];

/** 未装配时的占位：装配是必经路径，占位只是让字段不必每个使用点判空。 */
const UNINSTALLED: ConfigDeps = { logger: { warn: () => {} } };

const NOOP = (): void => {};

/** 通知设置：本插件配置文件的唯一存取点。 */
class ConfigStore {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;
  /** 落盘路径：DSH home 由环境决定、进程内不变，故随实例一次性定下。 */
  private readonly file = notifierFile(CONFIG_FILE_NAME);
  /** 装配入参（失败出口）。 */
  private deps: ConfigDeps = UNINSTALLED;
  /** 文件内容原样镜像：写回时以它为基底，才不会被一次保存抹掉不认识的键。 */
  private stored: StoredSettings = {};
  /** 用户层（净化后）：写面做掩码还原、视图做回显都要它。 */
  private user: Partial<NotifyConfig> = {};
  /** 生效设置：用户层归一化后的形态，读面直接给它。 */
  private effective: NotifyConfig = DEFAULT_CONFIG;
  /** 用户层修订号（内容摘要）：乐观并发的比较依据。 */
  private revision = 0;
  /** 写队列尾：新写挂在它后面，「读-改-写」不会交错。 */
  private tail: Promise<void> = Promise.resolve();

  /** 装配：读一次文件定下初值；此后只经 `write` 变更。 */
  install(deps: ConfigDeps): void {
    if (this.installed) throw new Error("dsh-notifier: config 域只能装配一次");
    this.installed = true;
    this.deps = deps;
    const read = readTextFileSync(this.file);
    // 没有文件与文件是空的，对读面是同一件事：都没有用户层。
    this.adopt(read.ok ? parseJsonObject(read.text) : {});
  }

  /** 卸载：放开装配入参并丢掉用户层快照——它同时是「用户层」与「磁盘状态」的记忆。 */
  release(): void {
    this.installed = false;
    this.deps = UNINSTALLED;
    this.adopt({});
  }

  /** 当前生效设置（含明文凭据；不外发）。 */
  current(): NotifyConfig {
    return this.effective;
  }

  /** 设置页视图：脱敏后的用户层与生效值 + 修订号 + 可写性，同一刻取齐。 */
  view(): SettingsView {
    return {
      // `user` 是**存储原样**（只掩码）：陌生键也要看得见——净化后的 this.user 里没有它们，
      // 而它们确实还在文件里，视图不显示就等于「文件里有、界面里没有」两套事实。
      user: redactStored(this.stored),
      revision: this.revision,
      writable: true,
      effective: redactConfig(this.effective),
    };
  }

  /**
   * 写：掩码还原 → 校验 → 合并 → 落盘 → 刷新快照。
   *
   * 顺序不可换：掩码不是合法密钥值，未还原就被校验拦死；校验早于落盘，否则非法值会先写进文件。
   * 校验与合并之间不净化：陌生键是透传保留的，一次保存不该把它们抹掉。0.2.3 的顶层渠道键已由
   * upgrade 域在装配期搬走，写面收到它们会被校验直接拒（退役键清单），不在这里做二次翻译。
   */
  async write(patch: SettingsPatch, expectedRevision?: number): Promise<WriteResult> {
    const restored = this.restoreSecrets(patch);
    if (!restored.ok) {
      return {
        ok: false,
        reason: "invalid",
        error: { key: "channels", hint: NEW_CHANNEL_MASK_HINT },
      };
    }
    const verdict = validateSettings(restored.patch);
    if (!verdict.ok) return { ok: false, reason: "invalid", error: verdict.error };

    const incoming = writableEntries(restored.patch);
    return this.enqueue(() => this.commit(incoming, expectedRevision));
  }

  /**
   * 提交：版本比对 → 合并 → 原子落盘 → 采纳。
   *
   * 整段在写队列内执行：比对与写入之间若能被另一次写插入，乐观并发就形同虚设
   * ——两次写都读到同一旧版本、都判定通过，后写的把先写的悄悄覆盖。
   */
  private async commit(incoming: StoredSettings, expectedRevision?: number): Promise<WriteResult> {
    if (expectedRevision !== undefined && expectedRevision !== this.revision) {
      return { ok: false, reason: "conflict" };
    }
    const merged: StoredSettings = { ...this.stored, ...incoming };
    const written = await writeTextAtomic(this.file, `${JSON.stringify(merged, null, 2)}\n`);
    if (!written.ok) {
      this.deps.logger.warn(`dsh-notifier: 配置写入失败 — ${written.reason}`);
      return { ok: false, reason: "unavailable" };
    }
    this.adopt(merged);
    return { ok: true, view: this.view() };
  }

  /** 文件内容到达：镜像原样留下，用户层与生效值由它派生。 */
  private adopt(stored: StoredSettings): void {
    this.stored = stored;
    this.user = sanitizeSettings(stored);
    this.effective = normalizeConfig(stored);
    this.revision = revisionOf(stored);
  }

  /** 掩码还原：patch 里等于掩码的密钥字段按 id 换回用户层原值；只有带了频道才需要这一步。 */
  private restoreSecrets(patch: SettingsPatch): RestoredPatch {
    const channels = patch.channels;
    if (channels === undefined) return { ok: true, patch };
    const restored = unmaskChannels(channels, this.user.channels);
    return restored.ok
      ? { ok: true, patch: { ...patch, channels: restored.channels } }
      : { ok: false };
  }

  /** 把一次写挂到队列尾；前一次无论成败，后一次都照常执行。 */
  private enqueue(task: () => Promise<WriteResult>): Promise<WriteResult> {
    const result = this.tail.then(task, task);
    this.tail = result.then(NOOP, NOOP);
    return result;
  }
}

/** 本域唯一的存取点实例：类不外放，外面 `new` 不出第二份设置状态。 */
export const configStore = new ConfigStore();

/** 提交体 → 可写入的原始设置：只剔除原型链危险键，契约不认识的键原样放行（抹掉属于静默破坏）。 */
function writableEntries(patch: SettingsPatch): StoredSettings {
  const entries: Record<string, RawSettingValue> = {};
  for (const [key, value] of Object.entries(patch)) {
    if (value === undefined || UNSAFE_KEYS.includes(key)) continue;
    entries[key] = value;
  }
  return entries;
}

/**
 * 修订号：用户层内容的摘要。
 *
 * 键序不是内容，换键序不该算改动；但排序必须**递归**做——`JSON.stringify` 的 replacer
 * 数组会作用到每一层，用它排顶层键会把嵌套键（频道、免打扰、路由表）统统丢掉，两份内容
 * 不同的设置于是算出同一个修订号，乐观并发的版本冲突漏判。
 */
function revisionOf(stored: StoredSettings): number {
  return createHash("sha256").update(stableJson(stored), "utf8").digest().readUInt32BE(0);
}

/** 稳定序列化：对象递归按键排序，数组保持原序（数组顺序是内容的一部分）。 */
function stableJson(value: RawSettingValue): string {
  if (isJsonArray(value)) return `[${value.map(stableJson).join(",")}]`;
  if (isJsonObject(value)) {
    const fields = Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${stableJson(value[key])}`);
    return `{${fields.join(",")}}`;
  }
  return JSON.stringify(value);
}

/** JSON 数组：`readonly` 数组落在 `Array.isArray` 的收窄结果之外，用守卫补上。 */
function isJsonArray(value: RawSettingValue): value is readonly RawSettingValue[] {
  return Array.isArray(value);
}

/** JSON 对象：排除数组与 `null`（`typeof null` 也是 `"object"`）。 */
function isJsonObject(value: RawSettingValue): value is StoredSettings {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

packages/dsh-notifier/test/integration/r.source:
/**
 * dsh-notifier — 组合根（`src/index.ts`）的真实 cordis Context 集成测试。
 *
 * 面口径：这里测的是**宿主看见的那一面**——`apply` 收窄宿主上下文、按序装配八个域、卸载逆序释放。
 * 这些行为只有放进真实 cordis 才成立：`inject` 门（未就绪不装配）、两条 waterfall 的 `prepend`
 * 链序、`{ global: true }` 的作用域过滤、`ctx.effect` 的卸载时机、`internal/service` 的晚到通知。
 * 假宿主只提供 `webServer`（组合根唯一触碰的宿主服务）与可选的 `settings`；事件总线、落盘、
 * 裁决管线全是真的——**不 mock `@deepseek-ai/cordis`**，也不用 `vi.mock`/`vi.fn`。
 *
 * 落盘隔离（红线）：config / stores / stream 的单例在**模块加载期**就用 `notifierFile()` 定死了
 * 路径，所以必须先把 `DSH_HOME` 指到 `mkdtempSync` 出的临时目录，再用**动态 `import()`** 拉组合根。
 * 写反了本节全部落盘就进真实 `~/.dsh`——那正是正在跑的 `dsh web` 的 home。
 *
 * 写队列纪律：历史与配置的落盘是 fire-and-forget（写队列是模块级字段，`release` 不清它），故每个
 * 产生落盘的用例都要等到自己那一条在磁盘上可见才算完；需要「没有新写入」这类否定判据时，用
 * `stores` 域自己的写口排一次队当**界碑**——队列串行，界碑落盘即此前排队的全部落盘。
 *
 * 时间纪律：本文件不钉系统时钟，`pollUntil` 的 deadline 读的正是 `Date.now()`，钉住它失败会从
 * 「断言红」退化成挂死。`afterEach` 仍还原一次，防将来有人在用例里钉。
 */
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { Context } from "@deepseek-ai/cordis";
import type { Events, Fiber, ThisType as EventThis } from "@deepseek-ai/cordis";
import type { Agent } from "@deepseek-ai/dsh-agent";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import type { Session, SessionEvent } from "@deepseek-ai/dsh-session";
import type { ApprovalOutcome, ApprovalRequest } from "@deepseek-ai/dsh-user-approval";
import type {
  AskUserQuestionAnswer,
  AskUserQuestionRequest,
} from "@deepseek-ai/dsh-user-questions";

import {
  assertEventReachability,
  assertRealCordisContextSemantics,
} from "../../../../test/smoke-lib.ts";
import { pollUntil, settleMicrotasks, tempDshHome } from "../helpers.ts";

// DSH_HOME 必须先于被测模块求值：三个单例的落盘路径在构造时定下，而静态 import 会在任何语句
// 之前执行——顺序反了，本节全部落盘就写进真实 `~/.dsh`。
const home = tempDshHome();
const notifier = await import("../../src/index.ts");
const apiApi = await import("../../src/server/api/interface.ts");
const configApi = await import("../../src/server/config/interface.ts");
const sdkApi = await import("../../src/server/sdk/interface.ts");
const storesApi = await import("../../src/server/stores/interface.ts");
const sharedApi = await import("../../src/server/shared/interface.ts");

/** 本插件的落盘位置（新布局：包私有目录，见 `shared/paths.ts`）。 */
const storageDir = join(home.dir, "@wingsky-1", "dsh-notifier");
const configFile = sharedApi.notifierFile(sharedApi.CONFIG_FILE_NAME);
const historyFile = sharedApi.notifierFile(sharedApi.HISTORY_FILE_NAME);
const seqFile = sharedApi.notifierFile(sharedApi.SEQ_FILE_NAME);
const versionFile = sharedApi.notifierFile(sharedApi.VERSION_FILE_NAME);

/** 种下的那份配置的原文：否定判据用它比对「一个字节都没动过」。 */
function seededConfig(): string {
  return `${JSON.stringify(BASE_SETTINGS, null, 2)}\n`;
}

/** 宿主契约冻结的 8 条浏览器端点（客户端锁定，独立抄写才守得住改路径）。 */
const ROUTE_PATHS: readonly string[] = [
  "/api/dsh-notifier/config",
  "/api/dsh-notifier/history",
  "/api/dsh-notifier/status",
  "/api/dsh-notifier/kinds",
  "/api/dsh-notifier/test",
  "/api/dsh-notifier/health",
  "/api/dsh-notifier/diagnostics",
  "/api/dsh-notifier/events",
];

/**
 * 基础设置：系统出口整个关掉、浏览器出口只弹不响。
 *
 * 系统出口在 Linux 会真的 spawn `notify-send`——测试不该在开发机上弹通知；浏览器出口的帧则
 * 经组合根的 `FrameBus` 进 api 域的流（只写 `seq.json`），是本文件观察「帧走出去了」的唯一手段。
 * 两条内置频道的形态**显式写出来**：`enabled` 是频道唯一的投递闸门，靠 `systemNotify:false`
 * 之类的弹窗键关不掉它（那只让出口无事可做，仍会留下一条 skipped 明细）。
 * `historyMaxAgeDays` 取**非默认值**：逆序释放那条判据要一个与默认值不同的可辨读数。
 */
const BASE_SETTINGS = {
  channels: [
    {
      type: "browser",
      id: "browser",
      enabled: true,
      popup: true,
      sound: false,
      whenVisible: false,
    },
    { type: "system", id: "system", enabled: false, popup: false, sound: false },
  ],
  historyMaxAgeDays: 7,
} as const;

/** 历史行：只取本文件当判据的字段（整体比较会把域内文案变化变成假红）。 */
interface HistoryLine {
  kind?: string;
  message?: string;
  suppressed?: string;
  channels?: ReadonlyArray<{ channelId: string; status: string }>;
}

/** 磁盘上的历史记录。 */
function historyLines(): HistoryLine[] {
  let text: string;
  try {
    text = readFileSync(historyFile, "utf8");
  } catch {
    return [];
  }
  return text
    .split("\n")
    .filter(Boolean)
    .flatMap((line) => {
      try {
        return [JSON.parse(line) as HistoryLine];
      } catch {
        // 坏行不当判据，也不吞掉同行之外的记录
        return [];
      }
    });
}

/** 某一种通知落了几条。 */
function countKind(kind: string): number {
  return historyLines().filter((line) => line.kind === kind).length;
}

/** 磁盘上第一条某一种通知：`beforeEach` 清过历史，所以不受上一个用例干扰。 */
function kindLine(kind: string): HistoryLine | undefined {
  return historyLines().find((line) => line.kind === kind);
}

/** 界碑用的种类名：只出现在界碑行里，任何通知判据都不会撞上它。 */
const SENTINEL_KIND = "itest-sentinel";

/**
 * 排一次界碑并等它落盘，用来给**否定**判据划界。
 *
 * 写队列串行，界碑在磁盘上可见即此前排队的写入全部落盘；没有界碑的「没有新记录」只是抢跑得来的
 * ——它证明的是「还没写完」，不是「不会写」。
 */
async function settleHistory(): Promise<void> {
  storesApi.appendHistory({ ts: Date.now(), kind: SENTINEL_KIND, title: "界碑", message: "-" });
  await pollUntil(() => historyLines().some((line) => line.kind === SENTINEL_KIND), "界碑落盘");
}

/** 浏览器出口的序号：`seq.json` 前进一格 = 帧真的走完了 FrameBus → api 域 → 流。 */
function seqValue(): number {
  try {
    const parsed = Number.parseInt(readFileSync(seqFile, "utf8").trim(), 10);
    return Number.isFinite(parsed) ? parsed : 0;
  } catch {
    return 0;
  }
}

/**
 * 本用例的序号锚点（每轮 +1000）。
 *
 * 序号是 fire-and-forget 写，「等于锚点 +1」这类判据要挡得住上一个用例迟到的那一笔——递增的锚点
 * 让迟到的值必然小于本轮的起点，于是「文件里出现了本轮的格子」只可能由本轮自己的广播产生。
 */
let seqAnchor = 0;

function seedSeqAnchor(): void {
  seqAnchor += 1000;
  mkdirSync(dirname(seqFile), { recursive: true });
  writeFileSync(seqFile, `${seqAnchor}\n`);
}

/** 写一份设置文件（组合根装配时同步读它，故必须用同步写）。 */
function seed(settings: Record<string, unknown>): void {
  mkdirSync(dirname(configFile), { recursive: true });
  writeFileSync(configFile, `${JSON.stringify(settings, null, 2)}\n`);
}

/** 假会话日志条目：本块只读 `type` 与 `data`（与 events 域单测同一口径）。 */
function turnEndEvent(turn: number, kind: string): SessionEvent {
  return { type: "turn/end", data: { turn, reason: { kind } } } as unknown as SessionEvent;
}

/** 假 agent：只露出 events 域真的会读的几处（`id` 与 `session` 的 header / 日志快照）。 */
function fakeAgent(
  id: string,
  events: SessionEvent[] = [],
  header: Record<string, unknown> = {},
): Agent {
  return {
    id,
    session: { header, snapshotEvents: () => events },
  } as unknown as Agent;
}

/** 假会话：`session/event` 的载荷带整份会话对象，而本插件只用它的 `id`。 */
function fakeSession(id: string): Session {
  return { id } as unknown as Session;
}

/**
 * 宿主按作用域派发时传的 `this`：`agent/*` 声明的是 `Scoped<Agent>`、`session/event` 是
 * `Scoped<Session>`，而那个 brand 不是本包的依赖，故从事件签名上取 `this` 位。测试要造的正是
 * `{ [Context.filter]: … }` 这一个成员——直接抄 `Scoped<…>` 会把它变成第二份事实源。
 */
type ScopedThis<K extends keyof Events> = EventThis<Events[K]>;

/** 作用域收紧的派发载体：filter 恒假，于是**只有** `{ global: true }` 的订阅能收到。 */
function scopeRejecting<K extends keyof Events>(): ScopedThis<K> {
  return { [Context.filter]: () => false } as unknown as ScopedThis<K>;
}

/**
 * 假 settings 服务只提供 describe 低优先级兜底；正式历史来源由 upgrade 域直接读取 DSH_HOME 双文件。
 * `describe()` 在真实宿主里只列**已注册**的命名空间，所以这里的 `user` 用三种取值对应三种真实形态：
 * `undefined` = 没注册这条命名空间（新架构的常态，服务面读不到）；`{}` = 注册了但 user 层为空；有键 = 注册且用户设过。
 */
function fakeSettings(user: Record<string, unknown> | undefined): { describe: () => unknown[] } {
  return {
    describe: () => (user === undefined ? [] : [{ ns: "dsh-notifier", user }]),
  };
}

/**
 * 假宿主 webServer：只实现组合根够得着的那一面（`register`），并记下摘除时的现场。
 *
 * `failAt` 让第 N 条摘除器抛错——宿主摘路由失败是真实会发生的（路由已被别人摘掉、宿主换实现），
 * 组合根的释放壳对它的承诺是「不阻断其余」。
 */
function fakeWebServer(
  observe: () => { configDays: number; serviceAlive: boolean },
  options: { failAt?: number } = {},
) {
  const routes: WebRoute[] = [];
  const removals: Array<{ path: string; configDays: number; serviceAlive: boolean }> = [];
  const service = {
    register(route: WebRoute) {
      routes.push(route);
      return () => {
        removals.push({ path: route.path, ...observe() });
        if (removals.length === options.failAt) throw new Error(`摘除失败：${route.path}`);
      };
    },
  } as unknown as Context["webServer"];
  return { service, routes, removals };
}

/** 假宿主 agent 注册表：只实现组合根读的两处（`get` 与 `isOwnedBy`）。 */
function fakeAgents(parent: Agent, child: Agent): Context["agents"] {
  return {
    get: (id: string) => (id === parent.id ? parent : undefined),
    isOwnedBy: (id: string, owner: Agent) => id === child.id && owner === parent,
  } as unknown as Context["agents"];
}

/**
 * 日志出口：`LoggerService` 的公开扩展点，用它把 warn 收进数组。
 *
 * 为什么不读内置的 `ctx.logger.buffer`：那个出口的阈值是 INFO，warn（级别 2）落在它之外，
 * buffer 里永远看不到本文件的判据文案。阈值按 `levels.default` 给——它是出口自己的约定。
 */
function captureWarnings(root: Context): string[] {
  const warnings: string[] = [];
  root.logger.exporter({
    levels: { default: 2 },
    export: (message) => {
      if (message.type === "warn") warnings.push(String(message.args[0]));
    },
  });
  return warnings;
}

/** 一次挂载的全部观测物。 */
interface Mounted {
  readonly root: Context;
  readonly fiber: Fiber;
  readonly host: ReturnType<typeof fakeWebServer>;
  /** 宿主日志出口收到的 warn 文案（组合根只经它报错）。 */
  readonly warns: string[];
  unmount(): Promise<void>;
}

/** 已挂载但用例没显式卸载的实例：`afterEach` 兜底收掉，免得路由/心跳漏到下一个用例。 */
let live: Fiber | null = null;

/**
 * 按宿主的真实挂载顺序装配：先 provide 宿主服务，再 `ctx.plugin(插件)`。
 *
 * `settings` 是本插件的**显式依赖**（组合根的 `inject`）：宿主保证它在插件装配前就绪，所以这里
 * 总是先 provide 一个假的；`settings` 的值就是那份 0.2.3 存量命名空间的 user 层（缺省 = 有服务
 * 但没存量）。「服务没来」这条分支已不属于本插件——它变成 cordis 的 inject 门（见 inject 门用例）。
 * `services` 是其余宿主服务（如 `agents`）——装与不装是两条不同的判定路径。
 */
async function mount(options: {
  config?: { enabled?: boolean };
  settings?: Record<string, unknown>;
  services?: Record<string, unknown>;
}): Promise<Mounted> {
  const root = new Context();
  root.provide("settings", fakeSettings(options.settings));
  for (const [name, value] of Object.entries(options.services ?? {})) root.provide(name, value);
  const warns = captureWarnings(root);
  const host = fakeWebServer(() => ({
    configDays: configApi.readConfig().historyMaxAgeDays,
    serviceAlive: root.get("wingsky.notifier", false) !== undefined,
  }));
  root.provide("webServer", host.service);
  const fiber = await root.plugin(notifier, options.config);
  live = fiber;
  return {
    root,
    fiber,
    host,
    warns,
    unmount: async () => {
      live = null;
      await fiber.dispose();
    },
  };
}

/**
 * 模拟宿主内置 answerer：链上**更早注册**的那一个，它给出的判定就是这次请求的最终结果。
 * 它不调 `next()`——宿主自己的应答者拿到判定后即短路，这正是本插件必须 prepend 的理由。
 */
async function mountApprovalAnswerer(
  root: Context,
  calls: string[],
  outcome: ApprovalOutcome,
): Promise<Fiber> {
  return root.plugin((ctx) => {
    ctx.on("approval/request", () => {
      calls.push("answerer");
      return Promise.resolve(outcome);
    });
  });
}

/** 同上，提问那条链上的 answerer（两条 waterfall 同构，夹具分开写以免一条覆盖另一条）。 */
async function mountQuestionAnswerer(
  root: Context,
  calls: string[],
  answer: AskUserQuestionAnswer,
): Promise<Fiber> {
  return root.plugin((ctx) => {
    ctx.on("user-questions/request", () => {
      calls.push("answerer");
      return Promise.resolve(answer);
    });
  });
}

beforeEach(() => {
  // 单例的落盘路径跨用例不变，能重置的只有文件：不重置的话上一个用例的配置/历史就是本用例的起点。
  rmSync(historyFile, { force: true });
  rmSync(configFile, { force: true });
  // 正式历史来源也落在这个共享的临时 DSH_HOME 里；清掉双文件，避免上个用例的存量进入下个用例。
  rmSync(join(home.dir, "settings.yaml.imported"), { force: true });
  rmSync(join(home.dir, "settings.yaml"), { force: true });
  seedSeqAnchor();
  seed(BASE_SETTINGS);
});

afterEach(async () => {
  vi.useRealTimers();
  if (live) {
    const fiber = live;
    live = null;
    await fiber.dispose();
  }
  // api 域的装配标记只在它自己的 release() 走完时才复位，而有一条用例刻意让摘除器抛错把它停在
  // 半释放（那是它的判据）。这里无条件补一次收尾：域释放幂等，正常用例上是空转——不放在用例里
  // 是因为用例前面任何一条断言红了就会跳过补偿，后续用例会级联红成一片。
  apiApi.releaseApi();
});

afterAll(() => {
  home.dispose();
});

describe("装配与暴露", () => {
  it("装配即暴露：服务面挂在宿主上下文上（声明合并的读法可用），登记与发送当场可用", async () => {
    const { root, fiber, unmount } = await mount({});
    // 声明合并的读法可用，而且读到的是**同一个**对象：服务面经 `ctx.provide` 挂在宿主上下文上，
    // 不是又造了一份（再造一份就会有两个 apiVersion、两套登记表）。
    const service = root.get("wingsky.notifier", false);
    expect(fiber.ctx["wingsky.notifier"]).toBe(service);
    expect(service?.apiVersion).toBe(2);
    // 管理面（清单 / 确认）不进服务面：多给一样，兄弟插件就能替用户放行自己的通知种类。
    expect("confirmKind" in (service ?? {})).toBe(false);

    service?.registerKind({ id: "itest:face", label: "集成测试" });
    expect(sdkApi.listKinds()).toContainEqual({
      id: "itest:face",
      label: "集成测试",
      confirmed: false,
    });
    // 未确认的外部种类：送进的是真管线，出去的是一条「unlisted」归档（不是静默丢弃）。
    await service?.send({ kind: "itest:face", body: "正文" });
    await pollUntil(() => countKind("itest:face") === 1, "登记后的发送落史");
    expect(kindLine("itest:face")?.suppressed).toBe("unlisted");

    await unmount();
    // 卸载后消费方按「通知中心不在」降级：`get` 拿空而不是拿到半死对象。
    expect(root.get("wingsky.notifier", false)).toBeUndefined();
  });

  it("inject 门：两条宿主服务（webServer / settings）都就绪才装配，缺一条都不跑", async () => {
    const root = new Context();
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    const fiber = await root.plugin(notifier);
    live = fiber;

    // 缺依赖时的现场：插件没跑（路由为空、服务面没上），也没有装配失败的声音。
    expect(host.routes).toHaveLength(0);
    expect(root.get("wingsky.notifier", false)).toBeUndefined();

    // 只补一条还不够：settings 是显式依赖（存量配置的读取面），缺它时装配体一步都不该走。
    root.provide("webServer", host.service);
    await settleMicrotasks();
    expect(host.routes).toHaveLength(0);
    expect(root.get("wingsky.notifier", false)).toBeUndefined();

    root.provide("settings", fakeSettings({}));
    await fiber.await();
    expect(host.routes.map((route) => route.path)).toHaveLength(8);
    expect(root.get("wingsky.notifier", false)?.apiVersion).toBe(2);
  });

  /**
   * 宿主契约 canary——**不是本插件的判据**：两个共用 helper 都只在自己临时挂的监听器上断言 cordis
   * 的语义（未注入访问抛错 / 缺位 get 安全 / effect 真实清理 / 作用域过滤只放行 global），
   * 它们不触本插件的任何代码。放在一个用例里是因为两者共用同一次装配，判据互不相干。
   */
  it("宿主契约 canary：真实 Context 语义 + `{global:true}` 的作用域过滤语义（非本插件行为判据）", async () => {
    const { fiber, unmount } = await mount({});
    // 插件 fiber 的运行时上下文才是「真实」的那一份：root 语义下未注入访问会静默给 undefined，
    // 断言①在那里恒真——历史教训（根因 A：fake-ctx 把服务当普通属性注入）正是靠这条堵住的。
    // 断恒等而非断存在：`root.fiber` 也存在，只有插件 fiber 才带 `runtime`（根为 null）。
    expect(fiber.ctx.fiber).toBe(fiber);
    assertRealCordisContextSemantics(fiber.ctx);
    assertEventReachability(fiber.ctx, Context, "agent/status", {
      agent: fakeAgent("itest-reach"),
      status: "running",
    });
    await unmount();
  });

  it("挂载点总开关 enabled:false 抵达裁决层：请求照进管线，但记的是 disabled 而不是照常投递", async () => {
    const { root, unmount } = await mount({ config: { enabled: false } });
    root.emit("agent/error", {
      agent: fakeAgent("itest-disabled"),
      turn: 1,
      step: 1,
      error: new Error("炸了"),
    });
    await pollUntil(() => countKind("error") === 1, "总开关关闭时的归档");
    expect(kindLine("error")?.suppressed).toBe("disabled");
    // 关掉的是「投递」，不是「记录」：帧的写排在归档之前，归档已在磁盘上时序号若前进过就已可见
    // ——所以这里断「没走到下一格」而不是「等于锚点」，免得受上一个用例迟到的那一笔影响。
    expect(seqValue()).not.toBe(seqAnchor + 1);
    await unmount();
  });
});

describe("宿主路由注册与摘除", () => {
  it("apply 期间宿主收到恰好 8 条 exact 路由，路径集合就是客户端锁定的那一份", async () => {
    const { host, unmount } = await mount({});
    expect(host.routes.map((route) => route.path).sort()).toEqual([...ROUTE_PATHS].sort());
    expect(host.routes.every((route) => route.kind === "exact")).toBe(true);
    expect(host.removals).toHaveLength(0);
    await unmount();
  });

  it("卸载摘除全部 8 条路由，重复卸载不再摘第二次（卸载链可能走到不止一次）", async () => {
    const { host, fiber, unmount } = await mount({});
    await unmount();
    expect(host.removals.map((removal) => removal.path).sort()).toEqual([...ROUTE_PATHS].sort());

    await fiber.dispose();
    expect(host.removals).toHaveLength(ROUTE_PATHS.length);
  });
});

describe("waterfall 契约（审批 / 提问）", () => {
  it("approval/request：链头可达，且 next() 把判定原样交还给更早注册的短路 answerer", async () => {
    const root = new Context();
    const calls: string[] = [];
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    root.provide("webServer", host.service);
    root.provide("settings", fakeSettings({}));
    // 宿主的形态：内置 answerer 在本插件之前注册，并且**不调 next()**（GUI 应答后即短路）。
    await mountApprovalAnswerer(root, calls, "rejected");
    const fiber = await root.plugin(notifier);
    live = fiber;
    // 反向固化：不带 prepend 的后来者排在这个短路 answerer 之后，整条链对它不可见。
    const control: string[] = [];
    root.on("approval/request", async () => {
      control.push("late");
      return "cancelled";
    });

    const request = { toolName: "bash", reason: "要写文件" } as unknown as ApprovalRequest;
    const outcome = await root.waterfall("approval/request", request, async () => "unavailable");

    // ② 链路结果没被吞：最终判定仍来自 answerer（插件自己返回 undefined 时这里会是 undefined）。
    expect(outcome).toBe("rejected");
    // ③ answerer 确实被调用：插件的 next() 真的把判定交了回来。
    expect(calls).toEqual(["answerer"]);
    // ① 插件的处理器被调用：可达性只有它自己的副作用能证明（审批通知落史）。
    await pollUntil(() => countKind("ask") === 1, "审批通知落史");
    // 反向固化：同一个事件、同一次派发里，后注册的无 prepend 监听器被短路挡在外面。
    // （`control` 空是**夹具前提**——answerer 短路后链不再往下走，不是本插件的判据。）
    expect(control).toEqual([]);
    await fiber.dispose();
    live = null;
  });

  it("user-questions/request：第二条 waterfall 与审批同构（同一个链头与交还契约）", async () => {
    const root = new Context();
    const calls: string[] = [];
    const answer: AskUserQuestionAnswer = { answers: [{ id: "q1", selected: ["是"] }] };
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    root.provide("webServer", host.service);
    root.provide("settings", fakeSettings({}));
    await mountQuestionAnswerer(root, calls, answer);
    const fiber = await root.plugin(notifier);
    live = fiber;

    // 只给必需的 questions：形状合法，值与文案无关（文案归 translate 域的单测）。
    const request: AskUserQuestionRequest = { questions: [{ id: "q1", question: "选哪个？" }] };
    const outcome = await root.waterfall("user-questions/request", request, async () => ({
      answers: [],
    }));

    // 交还的是 answerer 的**整份**判定，不是被本插件加工过的形状。
    expect(outcome).toEqual(answer);
    expect(calls).toEqual(["answerer"]);
    await pollUntil(() => countKind("question") === 1, "提问通知落史");
    await fiber.dispose();
    live = null;
  });

  it("guard：处理器内部抛错不向宿主抛——提问链路照旧交出判定，只留一条 warn", async () => {
    const root = new Context();
    const calls: string[] = [];
    const warns = captureWarnings(root);
    const answer: AskUserQuestionAnswer = { answers: [{ id: "q1", selected: ["是"] }] };
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    root.provide("webServer", host.service);
    root.provide("settings", fakeSettings({}));
    await mountQuestionAnswerer(root, calls, answer);
    const fiber = await root.plugin(notifier);
    live = fiber;

    // 上游形状漂移：一条缺 `question` 文本的提问。它在编译期本就被拦住，而守卫存在的理由正是
    // 编译期管不到的那一侧——载荷跨宿主边界不受信。
    const drifted = { questions: [{ id: "q1" }] } as unknown as AskUserQuestionRequest;

    // 宿主链不被打断：本插件只是旁观者，抛出去会让 next() 不被调用（症状是「提问框不弹了」）。
    const outcome = await root.waterfall("user-questions/request", drifted, async () => ({
      answers: [],
    }));
    expect(outcome).toEqual(answer);
    expect(calls).toEqual(["answerer"]);

    // 不静默：文案只此一处，吞掉之后「通知不工作」会变成查不出原因的现象。
    const guardWarn = warns.find((line) => line.includes("宿主事件处理失败"));
    expect(guardWarn?.startsWith("dsh-notifier: 宿主事件处理失败 —— ")).toBe(true);

    // 同一层壳的另一支：宿主抛出来的可以**不是** Error（官方那边失败类型本就是 unknown），
    // 文案得照样出得来，而不是把一次宿主异常消化成空字符串。
    const hostile = {
      get toolName(): string {
        throw "宿主抛出的字符串";
      },
    } as unknown as ApprovalRequest;
    const second = await root.waterfall("approval/request", hostile, async () => "unavailable");
    expect(second).toBe("unavailable");
    expect(warns.some((line) => line.endsWith("宿主抛出的字符串"))).toBe(true);
    await fiber.dispose();
    live = null;
  });
});

describe("宿主事件可达性", () => {
  it("多会话派发下本插件的订阅仍可达：漏掉 {global:true} 的表现是「有些会话不通知」", async () => {
    const { root, unmount } = await mount({});
    const control: string[] = [];
    // 对照：同一个事件、同一次派发，没有 {global:true} 的订阅会被作用域过滤掉。
    // （`control` 空是**夹具前提**——cordis 的 filter 真的在拒人，不是本插件的判据。）
    root.on("agent/error", () => {
      control.push("untagged");
    });

    // 宿主按 agent 作用域派发时传的就是这样一个 thisArg（filter 决定哪些订阅可见）。
    const scoped = scopeRejecting<"agent/error">();
    root.emit(scoped, "agent/error", {
      agent: fakeAgent("itest-scope"),
      turn: 1,
      step: 1,
      error: new Error("炸了"),
    });

    await pollUntil(() => countKind("error") === 1, "作用域收紧下仍到达管线");
    // （`control` 空是**夹具前提**——cordis 的 filter 真的在拒人，不是本插件的判据。）
    expect(control).toEqual([]);
    await unmount();
  });

  /**
   * 余下四条全局订阅**各自**可证伪：上面 `agent/error` 那条只覆盖了一条订阅，而宿主契约 canary 里
   * 的 `assertEventReachability` 测的是 cordis 的过滤语义本身（它自己临时挂监听器），都没能证明这
   * 四条带没带 `{global:true}`——**旧版同名文件是靠扫 `src/index.ts` 源码文本断言「全部 `ctx.on`
   * 注册处带 `{global:true}`」的**（还带 `// @ts-nocheck`），重写改成纯运行时行为后这块守卫缺了一
   * 个口子，下面就是它的行为版替身。四条写在同一个用例里是为了省掉四次装配，但每一段都独立成立：
   * 删掉对应那行的 `GLOBAL_LISTEN`，只有该段会红。
   */
  it("四条全局订阅各自可证伪（旧源码文本扫描的行为版替身）：收紧派发下状态 / 会话 / turn / 消亡都仍到达", async () => {
    const { root, unmount } = await mount({});
    // agent/* 共用同一个 this 位类型，会话那条在会话那一侧，故造两个载体。
    const scopedAgent = scopeRejecting<"agent/status">();
    const scopedSession = scopeRejecting<"session/event">();
    const signal = new AbortController().signal;

    // ① agent/status：两跳判定照旧产出完成通知（证据取自日志快照，与会话推送无关）。
    const statusEvents: SessionEvent[] = [];
    const statusAgent = fakeAgent("itest-scope-status", statusEvents);
    root.emit(scopedAgent, "agent/status", { agent: statusAgent, status: "running" });
    statusEvents.push(turnEndEvent(1, "completed"));
    root.emit(scopedAgent, "agent/status", { agent: statusAgent, status: "idle" });
    await pollUntil(() => countKind("done") === 1, "① 作用域收紧下 agent/status 仍产出完成通知");

    // ② session/event：这条会话的日志快照是空的，完成判定只能靠推送来的那笔证据——收不到就没有通知。
    // 用「比前一段多一条」而不是绝对值：这一段的成立与否不该被上一段的条数绑住。
    const doneBeforePush = countKind("done");
    const pushAgent = fakeAgent("itest-scope-session");
    root.emit(scopedAgent, "agent/status", { agent: pushAgent, status: "running" });
    root.emit(
      scopedSession,
      "session/event",
      fakeSession("itest-scope-session"),
      turnEndEvent(1, "completed"),
    );
    root.emit(scopedAgent, "agent/status", { agent: pushAgent, status: "idle" });
    await pollUntil(
      () => countKind("done") === doneBeforePush + 1,
      "② 作用域收紧下 session/event 的推送证据仍被记账",
    );

    // ③ agent/turn-stopping：同一 turn 只发一次（去重状态机在收紧的派发下也要吃到这两跳）。
    // 本段只证明「到达并被记账」：本例的 notifyTurnEnd 是默认的 false，所以这条 turn-end 是以
    // suppressed 落的史——它分不出「发了」与「被压制」，投递面的判据在下面那条用例里。
    const turnAgent = fakeAgent("itest-scope-turn");
    root.emit(scopedAgent, "agent/turn-stopping", { agent: turnAgent, turn: 7, signal });
    await pollUntil(() => countKind("turn-end") === 1, "③ 作用域收紧下 turn 边界仍到达状态机");
    expect(kindLine("turn-end")?.suppressed).toBe("kind-off");
    root.emit(scopedAgent, "agent/turn-stopping", { agent: turnAgent, turn: 7, signal });
    await settleHistory();
    expect(countKind("turn-end")).toBe(1);

    // ④ agent/disposed：清账把那笔去重记录抹掉，否则同一个 id 复用后这一 turn 永远不再通知。
    const disposed = scopeRejecting<"agent/disposed">();
    root.emit(disposed, "agent/disposed", { agent: turnAgent });
    root.emit(scopedAgent, "agent/turn-stopping", { agent: turnAgent, turn: 7, signal });
    await pollUntil(() => countKind("turn-end") === 2, "④ 作用域收紧下消亡事件仍清账");
    await unmount();
  });

  it("agent/error：真实 emit 到达管线，错误原文经组合根收窄成文本落进历史", async () => {
    const { root, unmount } = await mount({});
    root.emit("agent/error", {
      agent: fakeAgent("itest-error"),
      turn: 2,
      step: 3,
      error: new Error("磁盘满了"),
    });
    // 宽类型（unknown）在这里做唯一一次收窄：域内拿到的必须是可展示的文本。
    root.emit("agent/error", {
      agent: fakeAgent("itest-error"),
      turn: 2,
      step: 4,
      error: 42,
    });
    await pollUntil(() => countKind("error") === 2, "两条错误通知落史");
    const lines = historyLines().filter((line) => line.kind === "error");
    expect(lines).toHaveLength(2);
    // 收窄的两支：Error 取 `message`，非 Error 用 `String()`。判据必须咬住「取 message」这个动作——
    // 正文模板是 `…：${文本}`，而 `String(new Error("磁盘满了"))` 是 `"Error: 磁盘满了"`，
    // 只断包含「磁盘满了」的话两种写法都过（恒真），故断紧贴前缀冒号的那一段 + 反断整对象形态。
    const messages = lines.map((line) => line.message ?? "").join("\n");
    expect(messages).toContain("：磁盘满了");
    expect(messages).not.toContain("Error: 磁盘满了");
    expect(messages).toContain("42");
    await unmount();
  });

  it("agent/status：裸 idle 不发通知，running→idle 两跳且日志里有本轮新证据才产出 done", async () => {
    const { root, unmount } = await mount({});
    // 会话日志是一段可增长的快照，本轮结束的证据在 running 之后才追加进来。
    // 「进入 running 时日志里已有的 turn/end 是上一轮的、不许当成本轮完成」（`证据源=快照冻结`）
    // 有专门的主：`test/unit/events/listen.test.ts`，此处不重复覆盖。
    const events: SessionEvent[] = [];
    const agent = fakeAgent("itest-done", events);

    // 「只有 running 被看见过，idle 才算一轮结束」这条已由 test/unit/events/listen.test.ts 单测
    // 守死（那边还多断了一条「不留诊断」），这里只走本层独有的两跳：running → turn/end → idle。
    root.emit("agent/status", { agent, status: "running" });
    events.push(turnEndEvent(1, "completed"));
    root.emit("agent/status", { agent, status: "idle" });
    await pollUntil(() => countKind("done") === 1, "完成通知落史");
    await unmount();
  });

  it("session/event：推送的 turn/end 被记账，缺了它完成判定退化成不发（唯一可辨的副作用）", async () => {
    const { root, warns, unmount } = await mount({});
    // 快照里没有 turn/end：完成判定只能靠 session/event 推来的那一条证据。
    const agent = fakeAgent("itest-push");
    const session = fakeSession("itest-push");

    root.emit("agent/status", { agent, status: "running" });
    root.emit("agent/status", { agent, status: "idle" });
    await pollUntil(
      () => warns.some((line) => line.includes("完成判定跳过")),
      "无证据时的跳过诊断",
    );
    expect(countKind("done")).toBe(0);

    root.emit("agent/status", { agent, status: "running" });
    root.emit("session/event", session, turnEndEvent(1, "completed"));
    root.emit("agent/status", { agent, status: "idle" });
    await pollUntil(() => countKind("done") === 1, "推送证据驱动的完成通知");
    await unmount();
  });

  it("agent/turn-stopping 与 agent/disposed：同一 turn 只发一次，agent 消亡后清账", async () => {
    seed({ ...BASE_SETTINGS, notifyTurnEnd: true });
    const { root, unmount } = await mount({});
    const agent = fakeAgent("itest-turn");
    const signal = new AbortController().signal;

    root.emit("agent/turn-stopping", { agent, turn: 7, signal });
    await pollUntil(() => countKind("turn-end") === 1, "turn-end 落史");

    // 落史本身只证明「事件到了状态机并写了一行」：notifyTurnEnd 关着时同一条也会以 turn-end 落史，
    // 只是带 suppressed。投递面要有自己的判据——出站明细与浏览器帧的序号。
    const delivered = kindLine("turn-end");
    expect(delivered?.suppressed).toBeUndefined();
    expect(delivered?.channels).toEqual([{ channelId: "browser", status: "ok" }]);
    await pollUntil(() => seqValue() === seqAnchor + 1, "帧经 FrameBus 出去");

    // 同一 turn 再来一次：去重状态机在真实事件链上也要成立（否则每步都弹一条）。
    root.emit("agent/turn-stopping", { agent, turn: 7, signal });
    // 界碑划界：不然「没有第二条」是抢跑得来的。
    await settleHistory();
    expect(countKind("turn-end")).toBe(1);

    // 消亡事件清掉去重记录：否则同一 id 复用后这一 turn 永远不再通知。
    root.emit("agent/disposed", { agent });
    root.emit("agent/turn-stopping", { agent, turn: 7, signal });
    await pollUntil(() => countKind("turn-end") === 2, "清账后同一 turn 可再发");
    await unmount();
  });

  it("浏览器出口拿到帧：投递经组合根 FrameBus 走到 api 域，序号前进一格", async () => {
    const { root, unmount } = await mount({});
    root.emit("agent/error", {
      agent: fakeAgent("itest-frame"),
      turn: 1,
      step: 1,
      error: new Error("炸了"),
    });
    await pollUntil(() => countKind("error") === 1, "投递归档");
    // 序号只在 api 域订阅到帧之后才前进：这一格同时证明 FrameBus 的 emit 与 onFrame 两端接上了。
    await pollUntil(() => seqValue() === seqAnchor + 1, "帧经 FrameBus 出去");
    const delivered = kindLine("error")?.channels?.[0];
    expect(delivered?.channelId).toBe("browser");
    expect(delivered?.status).toBe("ok");
    await unmount();
  });
});

describe("宿主 agent 注册表（子代理归属）", () => {
  it("注册表缺位：带 parentSession 的会话按主任务处理（宁可多报一条 done，不静默用户自己的任务）", async () => {
    const { root, unmount } = await mount({});
    // header 有 parentSession，但宿主没装 agents 服务：`ctx.get("agents", false)` 必须缺位安全，
    // 而不是抛错或把「查不到」当成「是子代理」——后者会让子代理的完成通知永远发不出去。
    const events: SessionEvent[] = [];
    const child = fakeAgent("itest-orphan", events, { parentSession: "itest-gone" });

    root.emit("agent/status", { agent: child, status: "running" });
    events.push(turnEndEvent(1, "completed"));
    root.emit("agent/status", { agent: child, status: "idle" });
    await pollUntil(() => countKind("done") === 1, "查不到父 agent 时按主任务报完成");
    expect(countKind("subagent-done")).toBe(0);
    await unmount();
  });

  it("注册表有据：确由父 agent 创建的会话落 subagent-done，而不是当成主任务再报一次", async () => {
    const parent = fakeAgent("itest-parent");
    const events: SessionEvent[] = [];
    const child = fakeAgent("itest-child", events, { parentSession: "itest-parent" });
    const { root, unmount } = await mount({ services: { agents: fakeAgents(parent, child) } });

    root.emit("agent/status", { agent: child, status: "running" });
    events.push(turnEndEvent(1, "completed"));
    root.emit("agent/status", { agent: child, status: "idle" });
    // 两跳判定的产物只有 kind 能区分：`done` 会让每个子代理都伪装成用户的主任务。
    await pollUntil(() => countKind("subagent-done") === 1, "子代理完成通知落史");
    expect(countKind("done")).toBe(0);
    await unmount();
  });
});

describe("宿主 settings 服务：装配期同步割接存量配置", () => {
  it("服务先于插件就绪：装配期读到存量并割接进当前配置文件（同步，没有「等一会儿」的窗口）", async () => {
    // 0.2.4 那一步只在刻度未到的装机上跑：真实升级场景就是把刻度退回起点；而 0.2.3 的装机
    // 没有这份配置文件（配置住在宿主 settings 里），割接就落在这一份新文件上。
    rmSync(versionFile, { force: true });
    rmSync(configFile, { force: true });
    const { unmount } = await mount({
      settings: { notifyTaskDone: false, notifySound: false, configFile: "/legacy/config.json" },
    });

    // 割接在装配期同步走完：装配返回时读面已经是割接后的形态，不需要轮询。
    expect(configApi.readConfig().notifyTaskDone).toBe(false);
    const stored = JSON.parse(readFileSync(configFile, "utf8")) as Record<string, unknown>;
    expect(stored.notifyTaskDone).toBe(false);
    // 旧键搬完即删：文件里只留条目一处表达
    expect("notifySound" in stored).toBe(false);
    // 两条内置条目被割接出来，旧的全局音效键摊到各自的 `sound` 上。
    expect(stored.channels).toEqual([
      { type: "browser", id: "browser", sound: false },
      { type: "system", id: "system", sound: false },
    ]);
    // 装配键（configFile）不进新配置：它在旧格式里就属于组合层的启动参数。
    expect("configFile" in stored).toBe(false);
    await unmount();
  });

  it("命名空间未注册时也能割接：存量只在 DSH_HOME 正式 settings.yaml 里", async () => {
    rmSync(versionFile, { force: true });
    rmSync(configFile, { force: true });
    writeFileSync(
      join(home.dir, "settings.yaml"),
      "dsh-notifier:\n  notifyTaskDone: false\n  notifySound: false\n",
      "utf8",
    );
    // `settings` 缺省 = 服务面里没有这条命名空间（新架构不注册它）：正式文件仍直接提供存量。
    const { unmount } = await mount({});

    const stored = JSON.parse(readFileSync(configFile, "utf8")) as Record<string, unknown>;
    expect(stored.notifyTaskDone).toBe(false);
    // 旧键搬完即删，且装配键不进新配置。
    expect("notifySound" in stored).toBe(false);
    expect(stored.channels).toEqual([
      { type: "browser", id: "browser", sound: false },
      { type: "system", id: "system", sound: false },
    ]);
    await unmount();
  });

  it("服务缺席即不装配：缺 settings 的 inject 门一步都不走，配置原样躺着；就绪后同一次装配里割接", async () => {
    rmSync(versionFile, { force: true });
    const root = new Context();
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    root.provide("webServer", host.service);
    const fiber = await root.plugin(notifier);
    live = fiber;
    await settleMicrotasks();

    // 缺依赖：装配没跑，也就没有人去读写配置——种下的那份逐字未动。
    expect(host.routes).toHaveLength(0);
    expect(root.get("wingsky.notifier", false)).toBeUndefined();
    expect(readFileSync(configFile, "utf8")).toBe(seededConfig());

    // 服务随后就绪：装配开始，割接与它同一次走完。
    root.provide("settings", fakeSettings({ notifyTaskDone: false }));
    await fiber.await();
    expect(host.routes).toHaveLength(ROUTE_PATHS.length);
    const stored = JSON.parse(readFileSync(configFile, "utf8")) as Record<string, unknown>;
    expect(stored.notifyTaskDone).toBe(false);
  });

  it("名字对不上与卸载后到来的服务都不触发割接（inject 认的是服务名，不是形状）", async () => {
    rmSync(versionFile, { force: true });
    const root = new Context();
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    root.provide("webServer", host.service);
    const fiber = await root.plugin(notifier);

    // ① 名字对不上：另一个恰好也带 describe 的服务不满足 inject，装配一步都不走。
    root.provide("otherHostService", fakeSettings({ notifyTaskDone: false }));
    await settleMicrotasks();
    expect(host.routes).toHaveLength(0);

    // ② 卸载之后才来的真服务：装配体已卸载，不会再被拉起来。
    await fiber.dispose();
    root.provide("settings", fakeSettings({ notifyTaskDone: false }));
    await settleMicrotasks();
    expect(host.routes).toHaveLength(0);
    expect(root.get("wingsky.notifier", false)).toBeUndefined();

    // 否定判据要一个界碑：config 域的写队列串行，本用例自己排一次队，它的落盘即此前全部落盘。
    const written = await configApi.writeConfig({ historyMaxAgeDays: 5 });
    expect(written.ok).toBe(true);
    const stored = JSON.parse(readFileSync(configFile, "utf8")) as Record<string, unknown>;
    expect("notifyTaskDone" in stored).toBe(false);
    expect(stored.historyMaxAgeDays).toBe(5);
  });
});

describe("释放", () => {
  it("卸载逆序：api 域先放（摘路由时设置读面与服务面都还在），服务面随 sdk 域最后消失", async () => {
    const { root, host, unmount } = await mount({});
    await unmount();

    // 摘除发生在 api 域释放的那一刻。正序释放会让 config 域（先于 api 装配）已经放开入参，
    // 症状是「api 域在别人已放开的入参上继续服务」——这里读到的就是那个入参。
    expect(host.removals).toHaveLength(ROUTE_PATHS.length);
    for (const removal of host.removals) {
      expect(removal.configDays).toBe(7);
      expect(removal.serviceAlive).toBe(true);
    }
    // 全链走完之后：服务面收回、设置回落默认（config 域也释放了）。
    expect(root.get("wingsky.notifier", false)).toBeUndefined();
    expect(configApi.readConfig().historyMaxAgeDays).toBe(0);
  });

  it("卸载后事件与提交都不再进管线：没有新的历史落盘", async () => {
    const { root, warns, unmount } = await mount({});
    const payload = {
      agent: fakeAgent("itest-unload"),
      turn: 1,
      step: 1,
      error: new Error("炸了"),
    };
    root.emit("agent/error", payload);
    await pollUntil(() => countKind("error") === 1, "卸载前的归档");
    const service = root.get("wingsky.notifier", false);

    await unmount();
    root.emit("agent/error", payload);
    // 消费方可能握着卸载前的服务引用：那时 submit 必须被丢弃（不抛），而不是写进一个已释放的域。
    await service?.send({ kind: "done", body: "卸载后发送" });

    // 否定判据要界碑：重新装配一次，用 stores 域自己的写口排队，界碑落盘即此前排队的写入全部落盘
    // ——卸载后若真有人在服务且还写得动磁盘，那条 done 会排在界碑之前浮现。
    const again = await mount({});
    await settleHistory();
    expect(countKind("error")).toBe(1);
    expect(countKind("done")).toBe(0);
    // 光看历史不够：卸载后 stores 的写会被它自己的 UNINSTALLED 出口吞掉，泄漏的请求于是「写了但没
    // 落下」。投递那条路不会静默——真跑到投递层会撞上「投递块尚未装配」并出声，而界碑（pollUntil
    // 至少等过一个定时器）已保证在飞的那条链全部落定，所以这里读 warn 不是抢跑。
    expect(warns.filter((line) => line.includes("投递失败"))).toEqual([]);
    await again.unmount();
  });

  it("宿主 webServer 被收回（热重载）：本插件随之卸载，路由全部摘除、服务面收回", async () => {
    const root = new Context();
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    const webServer = root.provide("webServer", host.service);
    root.provide("settings", fakeSettings({}));
    const fiber = await root.plugin(notifier);
    live = fiber;
    expect(host.routes).toHaveLength(ROUTE_PATHS.length);

    // 宿主收回服务：依赖它的 fiber 必须自己卸载——挂着不走的症状是「宿主已经换了 webServer，
    // 旧路由还挂在新服务器上」，而插件看起来一切正常。
    await webServer();
    live = null;
    expect(host.removals.map((removal) => removal.path).sort()).toEqual([...ROUTE_PATHS].sort());
    expect(root.get("wingsky.notifier", false)).toBeUndefined();
  });

  it("单个域释放失败不阻断其余：一条路由摘除抛错，卸载链照样走完", async () => {
    const root = new Context();
    // 第 3 条摘除器抛错：宿主摘不掉路由是真实会发生的（路由已被别人摘掉、宿主换实现），
    // api 域的释放循环会停在它那里，而组合根的安全释放壳必须继续走完 sdk / events /
    // pipeline / stores / config——否则一次清理失败就拖垮整条卸载链。
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }), { failAt: 3 });
    root.provide("webServer", host.service);
    root.provide("settings", fakeSettings({}));
    const fiber = await root.plugin(notifier);
    live = fiber;

    await fiber.dispose();
    live = null;
    expect(host.removals).toHaveLength(3);
    // 链走完的两个凭据：服务面收回（sdk 域放过了）与设置回落默认（config 域也放过了）。
    // api 域停在半释放状态的收尾由 `afterEach` 无条件做（见那里的注释：用例内补偿会被断言红跳过）。
    expect(root.get("wingsky.notifier", false)).toBeUndefined();
    expect(configApi.readConfig().historyMaxAgeDays).toBe(0);
  });
});

/**
 * 隔离自证：本节全部落盘都必须住进临时 DSH_HOME。
 *
 * 它守的是本文件的**红线纪律**：单例在模块加载期定死路径，一旦动态 `import()` 排到了
 * `tempDshHome()` 之前，三个域的写入就全进真实 `~/.dsh`（正在跑的 `dsh web` 的 home），
 * 而那时下面这些读会当场落空。
 */
describe("落盘隔离", () => {
  it("历史、配置、序号三个域的文件都落在临时 DSH_HOME 的包私有目录里", async () => {
    const { root, unmount } = await mount({});
    root.emit("agent/error", {
      agent: fakeAgent("itest-home"),
      turn: 1,
      step: 1,
      error: new Error("炸了"),
    });
    await pollUntil(() => countKind("error") === 1, "归档落盘");
    await pollUntil(() => seqValue() === seqAnchor + 1, "序号落盘");

    // 路径同源：三个域名下的文件都是 `notifierFile()` 从同一个 DSH_HOME 拼出来的。
    expect(historyFile).toBe(join(storageDir, sharedApi.HISTORY_FILE_NAME));
    expect(configFile).toBe(join(storageDir, sharedApi.CONFIG_FILE_NAME));
    // 原子写会先落一个同目录临时文件（`<目标>.tmp-<pid>`），status 的防抖落盘可能正在飞：那是
    // 实现的中间物，不是布局的一部分，剔掉再比对。**要轮询**：清单在防抖窗口内本来就不齐，
    // 直接比会读到「前一个用例留下的文件」而看不出状态落盘整条坏掉（实测：把 status 的 debounce
    // 写改成永不执行，e2e 那条红、这条不轮询的版本全绿）。
    await pollUntil(() => {
      const names = readdirSync(storageDir).filter((name) => !name.includes(".tmp-"));
      return names.length === 5 && names.includes(sharedApi.STATUS_FILE_NAME);
    }, "五个存储文件落齐");
    expect(
      readdirSync(storageDir)
        .filter((name) => !name.includes(".tmp-"))
        .sort(),
    ).toEqual([
      sharedApi.CONFIG_FILE_NAME,
      sharedApi.HISTORY_FILE_NAME,
      sharedApi.SEQ_FILE_NAME,
      sharedApi.STATUS_FILE_NAME,
      sharedApi.VERSION_FILE_NAME,
    ]);
    // 内容也要对：路径存在不代表这次投递真的写进去了（status 是防抖落盘的，初值 `{}` 会先出现）。
    await pollUntil(() => {
      try {
        return readFileSync(join(storageDir, sharedApi.STATUS_FILE_NAME), "utf8").includes(
          "browser",
        );
      } catch {
        return false;
      }
    }, "状态里出现本次投递的频道");
    // 配置读的是本用例种下的那份（临时目录里的），落的历史也是本次 run 写的。
    expect(configApi.readConfig().historyMaxAgeDays).toBe(7);
    expect(readFileSync(historyFile, "utf8")).toContain('"kind":"error"');
    await unmount();
  });
});

